package main

// 这行注释紧贴 import 说明：标准库分组、第三方分组、本项目分组
// gofmt 会自动帮你排好，但分组是作者的责任
import (
	"fmt" // 标准库

	"github.com/xuesh/homecube/lab/s1/d01/greeter" // 本项目的包
)

// func main 是入口。main 包里只能有一个 main 函数
func main() {
	// 1) 调用导出函数 Greet（大写）
	fmt.Println(greeter.Greet("HomeCube"))

	// 2) 调用小写函数 greet 会编译失败：
	//    cannot refer to unexported name greeter.greet
	// fmt.Println(greeter.greet("HomeCube"))

	// 3) 调用常量与结构体构造也一样，取决于首字母
	c := greeter.NewMember("小林", "owner")
	fmt.Printf("成员: %+v\n", c)

	// 4) %T 打印类型，%v 打印值，%+v 打印字段名 —— 调试三件套
	fmt.Printf("类型=%T 值=%v 详情=%+v\n", c, c.ID, c)

	// 5) 统计包里有什么：go doc 可以把导出的东西列出来
	fmt.Println("包文档：go doc github.com/xuesh/homecube/lab/s1/d01/greeter")
}

