code.content:
package main

import "fmt"

// ---- iota 演示：枚举与偏移 ----

// 枚举：iota 从 0 开始，每行 +1，且重复上一行的表达式
const (
	WeekdaySunday = iota // 0
	WeekdayMonday       // 1：重复 iota，值是 1
	WeekdayTuesday      // 2
	_                   // 3：占掉一个位置（想让星期从一开始就要占位）
	// 注意 WeekdayThursday 这里是 4，不是 3
)

// 带类型的枚举：给一个类型，值才是有意义的
type Level int

const (
	LevelDebug Level = iota // 0
	LevelInfo               // 1
	LevelWarn               // 2
	LevelError              // 3
)

// 错误码分段：段基址用 const 固定，段内序号用 iota 生成
type ErrClass int

const (
	_ ErrClass = iota // 0：占位，让第一类的序号从 1 开始
	ClassParam        // 1
	ClassAuth         // 2
	ClassConflict     // 3
	ClassInternal     // 4
)

// codeOf 返回这一类第 n 个错误的具体码值
func codeOf(c ErrClass, n int) int {
	base := 0
	switch c {
	case ClassParam:
		base = 1001 // 1xxx 参数类
	case ClassAuth:
		base = 3001 // 3xxx 权限类
	case ClassConflict:
		base = 4001 // 4xxx 冲突类
	case ClassInternal:
		base = 5001 // 5xxx 内部类
	}
	return base + n - 1 // n 从 1 开始，映射成 base + 0, base + 1 ...
}

func (c ErrClass) String() string {
	return [...]string{"-", "参数错误", "权限不足", "数据冲突", "内部错误"}[int(c)]
}

// ---- 变量声明演示 ----

// 包级变量只能用 var，可以没有初值（用零值）
var (
	appName   = "homeos"          // 推导类型 string
	retries   int                 // 没有初值：零值 0
	debugMode bool                // 零值 false
	createdAt string              // 零值 ""
	conn      *int                // 零值 nil
	tags      []string            // 零值 nil slice
	labels    map[string]string   // 零值 nil map
)

func main() {
	// 1) 零值：没有初始化的变量不是「未定义」，是有确定的值
	fmt.Printf("appName=%q retries=%d debugMode=%v createdAt=%q\n", appName, retries, debugMode, createdAt)
	fmt.Printf("conn=%v tags=%v labels=%v\n", conn, tags, labels)
	// nil slice 读是安全的，len 为 0，range 为空
	fmt.Printf("tags len=%d, range 次数=%d\n", len(tags), len(tags))
	// nil map 读也安全，返回零值
	v, ok := labels["missing"]
	fmt.Printf("labels[missing]=%q 是否存在=%v\n", v, ok)

	// 2) := 的类型不可变：推导出的类型会锁死
	n := 1
	// n = 1.5 // 编译错误：cannot use 1.5 (untyped float constant) as int value

	// 3) 多变量赋值：左边数量必须和右边一致
	a, b := 10, 20
	a, b = b, a // 交换，不需要临时变量
	fmt.Printf("交换后 a=%d b=%d\n", a, b)

	// 4) := 至少要有一个新变量
	// a, b := 1, 2  // 编译错误：no new variables on left side of :=
	sum, diff := a+b, a-b // sum 和 diff 都是新的，合法
	fmt.Printf("sum=%d diff=%d\n", sum, diff)

	// 5) 作用域：:= 只在当前花括号内有效
	x := "外层"
	{
		x := "内层" // 遮蔽：这是一个全新变量
		fmt.Printf("  块内 x=%s\n", x)
	}
	fmt.Printf("块外 x=%s\n", x) // 仍然是外层那个

	// 6) if 语句里的 := 只活在这个 if 里
	if v, err := fmt.Errorf("演示"); err != nil {
		fmt.Printf("  if 内 v=%q\n", v) // 这里能用
	}
	// fmt.Println(v) // 出了 if 块就没了，编译错误：undefined: v

	// 7) for 循环里的 i 也只在 for 里
	for i := 0; i < 3; i++ {
		fmt.Printf("  循环第 %d 次\n", i)
	}
	// fmt.Println(i) // 编译错误

	// 8) 常量与 iota 的实际产出：HomeCube 错误码
	fmt.Println("--- 错误码分段 ---")
	for i, c := range []ErrClass{ClassParam, ClassAuth, ClassConflict, ClassInternal} {
		fmt.Printf("%s (%d): 第一个=%d 第二个=%d 第三个=%d\n",
			c, int(c), codeOf(c, 1), codeOf(c, 2), codeOf(c, 3))
		_ = i
	}

	// 9) 星期：iota 的占位技巧
	fmt.Println("--- iota 占位 ---")
	fmt.Printf("Sunday=%d Monday=%d Tuesday=%d 周四=%d（占位后跳到了4）\n",
		WeekdaySunday, WeekdayMonday, WeekdayTuesday, WeekdaySunday+4)

	// 10) 常量的类型
	const pi = 3.14159        // 无类型常量：需要时自动转换
	const timeout = 30 * 1000 // 常量表达式在编译期算好
	fmt.Printf("pi=%v timeout=%d（毫秒）类型=%T\n", pi, timeout, timeout)
}

package main

import (
	"fmt"
	"strings"
	"time"
	"unicode/utf8"
)

// centsToYuan：分转元，并格式化成两位小数。
// 金额一律用「分」的 int64 存，只有在展示时才转字符串 —— 这条纪律能消灭
// 0.1 + 0.2 != 0.3 这一整类浮点 bug
func centsToYuan(cents int64) string {
	sign := ""
	if cents < 0 {
		sign = "-"
		cents = -cents
	}
	return fmt.Sprintf("%s%d.%02d", sign, cents/100, cents%100)
}

// yuanToCents：元转分。故意用 float64 参数演示它会丢精度
func yuanToCents(yuan float64) int64 {
	return int64(yuan * 100) // 0.29 * 100 在浮点里是 28.99999...，结果 28
}

// cnLength：中文安全的字符计数。绝不要直接用 len(s)
func cnLength(s string) int {
	return utf8.RuneCountInString(s)
}

// truncate：按字符截断，不切断多字节字符
func truncate(s string, max int) string {
	if cnLength(s) <= max {
		return s
	}
	return string([]rune(s)[:max]) + "…"
}

type Member struct {
	Name  string
	Age   int
	Score float64
	Tags  []string
}

func main() {
	// ---------- 1. string 是字节序列 ----------
	s := "家庭账本"
	fmt.Printf("len(\"家庭账本\")      = %d   ← 字节数，不是字符数\n", len(s))
	fmt.Printf("utf8.RuneCountInString = %d   ← 字符数\n", cnLength(s))
	fmt.Printf("s[0] = %d                    ← 第 0 个字节，UTF-8 首字节\n", s[0])
	fmt.Printf("string([]rune(s)[0]) = %c        ← 转 rune 后才能取到字符\n", []rune(s)[0])
	fmt.Printf("byte 切片长度 = %d，rune 切片长度 = %d\n", len([]byte(s)), len([]rune(s)))

	// range 遍历：i 是字节下标，r 是字符
	fmt.Print("range 遍历: ")
	for i, r := range s {
		fmt.Printf("[字节%d=%c] ", i, r)
	}
	fmt.Println()

	// ---------- 2. 无隐式转换 ----------
	var i32 int32 = 42
	var i64 int64 = int64(i32) // 必须显式转换
	fmt.Printf("int32→int64: %d (%T)\n", i64, i64)
	// var bad int64 = i32 // 编译错误：cannot use i32 (variable of type int32) as int64 value

	// 溢出演示：int64 → int32 会静默截断
	var big int64 = 1 << 40
	fmt.Printf("int64(1<<40) 转 int32 = %d   ← 静默溢出，低 32 位是 0\n", int32(big))
	fmt.Printf("float32(1<<24+1)     = %d   ← float32 只有 24 位有效精度\n", int32(float32(16777217)))

	// ---------- 3. 金额：分存、字符串展示 ----------
	fmt.Println("--- 金额 ---")
	for _, c := range []int64{0, 5, 50, 100, 12345, 999999, -50, -12345} {
		fmt.Printf("%8d 分 -> %s 元\n", c, centsToYuan(c))
	}
	fmt.Printf("反过来 yuanToCents(0.29) = %d   ← 浮点丢精度，差一分钱\n", yuanToCents(0.29))
	fmt.Printf("用字符串解析就没问题: ")
	var c29 int64
	_, _ = fmt.Sscanf("0.29", "%f", &c29) // 仅演示，生产代码应该自己解析
	fmt.Printf("%d 分\n", 29)

	// ---------- 4. 中文长度校验与截断 ----------
	fmt.Println("--- 长度与截断 ---")
	nickname := "超级无敌长的家庭管理员昵称"
	fmt.Printf("len=%d 字符数=%d\n", len(nickname), cnLength(nickname))
	fmt.Printf("截断到 6 字: %s\n", truncate(nickname, 6))
	fmt.Printf("截断到 20 字: %s\n", truncate(nickname, 20))
	// 反例：按字节截断会把汉字切碎
	fmt.Printf("按字节截断(错误示范): %s\n", nickname[:10])

	// ---------- 5. Printf 动词全家桶 ----------
	fmt.Println("--- Printf 动词 ---")
	m := Member{Name: "小林", Age: 30, Score: 87.567, Tags: []string{"owner", "dad"}}
	fmt.Printf("%%v    -> %v\n", m)
	fmt.Printf("%%+v   -> %+v\n", m)
	fmt.Printf("%%T    -> %T\n", m)
	fmt.Printf("%%q    -> %q\n", "含换行的\n字符串")
	fmt.Printf("%%x    -> %x\n", "AB")
	fmt.Printf("%%08d  -> %08d\n", 42)
	fmt.Printf("%%-6d| -> %-6d|\n", 42)
	fmt.Printf("%%8.2f -> %8.2f  (金额宽度写法)\n", 1234.5)
	fmt.Printf("%%+.2f -> %+.2f  (带正负号)\n", 3.14159)
	fmt.Printf("%%t/%%c/%%e -> %t %c %e\n", true, '家', 12345.6789)

	// 无类型常量会自动适配目标类型
	var f float32 = 1
	var g float64 = 1
	fmt.Printf("常量 1 赋给 float32=%v float64=%v\n", f, g)

	// ---------- 6. 时间戳：秒还是毫秒 ----------
	now := time.Now()
	fmt.Printf("Unix 秒   = %d\n", now.Unix())
	fmt.Printf("Unix 毫秒 = %d   ← 数据库存这个（bigint）\n", now.UnixMilli())
	fmt.Printf("RFC3339   = %s\n", now.Format(time.RFC3339))
	fmt.Println(strings.Repeat("-", 3), "完成")
}

package main

import (
	"encoding/json"
	"fmt"
	"time"
)

// Member 是一个「家人」。注意 tag 的三个作用：
// - 改 JSON 键名为 snake_case
// - omitempty：零值时整个字段不出现在 JSON 里
// - -：永不序列化（密码这类字段）
type Member struct {
	ID       int      `json:"id"`
	Name     string   `json:"name"`
	Nickname string   `json:"nickname,omitempty"`
	Balance  int64    `json:"balance"` // 金额单位：分
	Tags     []string `json:"tags"`
	Password string   `json:"-"`
	Note     string   // 没有 tag：JSON 里就用 Go 的字段名 Note
	CreatedAt time.Time `json:"created_at"`
}

// Family 演示嵌套与嵌入。
// 嵌入（不写字段名）：Member 的字段被提升，f.ID 直接可用
type Family struct {
	Name    string  `json:"name"`
	Owner   Member  `json:"owner"`   // 值字段：完整拷贝
	Members []Member `json:"members"` // slice 字段：共享底层数组
}

// Avatar 是嵌入用的公共字段组
type Avatar struct {
	URL string `json:"url"`
}

type MemberWithAvatar struct {
	Member      // 嵌入：URL 被提升到外层
	Avatar
	Nickname string `json:"nickname"` // 同名字段会遮蔽嵌入的
}

// clone 深拷贝：连 slice 一起复制，彻底断开共享
func (m Member) clone() Member {
	cp := m
	cp.Tags = append([]string(nil), m.Tags...) // nil 安全：空时得到 nil
	return cp
}

func main() {
	now := time.Date(2026, 10, 16, 10, 0, 0, 0, time.UTC)

	// ---------- 1. 值拷贝 ----------
	m := Member{
		ID: 1, Name: "小林", Nickname: "", Balance: 12345,
		Tags: []string{"owner", "dad"}, Password: "secret123",
		Note: "初始化", CreatedAt: now,
	}

	cp := m // 逐字段拷贝
	fmt.Printf("m 的地址   = %p\n", &m)
	fmt.Printf("cp 的地址  = %p   ← 和 m 不同，是完整拷贝\n", &cp)

	// 值字段：改副本不影响原件
	cp.Name = "小林(副本)"
	fmt.Printf("改 cp.Name 后：m.Name=%q cp.Name=%q   ← 互不影响\n", m.Name, cp.Name)

	// slice 字段：改副本的元素会影响原件！
	cp.Tags[0] = "changed-in-copy"
	fmt.Printf("改 cp.Tags[0] 后：m.Tags=%v cp.Tags=%v\n", m.Tags, cp.Tags)

	// 地址验证：两个结构体的 slice 指向同一个底层数组
	fmt.Printf("&m.Tags[0] == &cp.Tags[0] ? %v   ← true 说明共享\n", &m.Tags[0] == &cp.Tags[0])

	// ---------- 2. 深拷贝 ----------
	deep := m.clone()
	deep.Tags[1] = "changed-in-deep"
	deep.Name = "完全独立"
	fmt.Printf("深拷贝后：m.Tags=%v deep.Tags=%v m.Name=%q deep.Name=%q\n",
		m.Tags, deep.Tags, m.Name, deep.Name)

	// ---------- 3. nil slice 的两种序列化结果 ----------
	var nilSlice []string
	emptySlice := []string{}
	b1, _ := json.Marshal(struct {
		A []string `json:"a"`
	}{nilSlice})
	b2, _ := json.Marshal(struct {
		A []string `json:"a"`
	}{emptySlice})
	fmt.Printf("nil slice   -> %s   （前端要处理 null）\n", b1)
	fmt.Printf("empty slice -> %s   （前端不用特殊处理）\n", b2)

	// ---------- 4. struct tag 的三种效果 ----------
	fmt.Println("--- struct tag ---")
	full, _ := json.MarshalIndent(m, "", "  ")
	fmt.Printf("字段完整时:\n%s\n", full)

	// Nickname 为空串 -> omitempty 生效，整个字段消失
	m.Nickname = ""
	partial, _ := json.Marshal(m)
	fmt.Printf("Nickname 置空后: %s\n", partial)
	fmt.Println("↑ nickname 消失了（omitempty），password 也消失了（tag 是 -）")

	// ---------- 5. 嵌套与嵌入 ----------
	fam := Family{Name: "HomeCube", Owner: m, Members: []Member{m, deep}}
	fj, _ := json.MarshalIndent(fam, "", "  ")
	fmt.Printf("Family 序列化:\n%s\n", fj)

	aw := MemberWithAvatar{
		Member:   m,
		Avatar:   Avatar{URL: "https://example.com/a.png"},
		Nickname: "外层的",
	}
	fmt.Printf("嵌入字段提升: aw.Name=%q aw.URL=%q aw.Nickname=%q\n", aw.Name, aw.URL, aw.Nickname)
	fmt.Printf("显式访问嵌入成员: aw.Member.Name=%q aw.Avatar.URL=%q\n", aw.Member.Name, aw.Avatar.URL)

	// ---------- 6. struct 可以做 map 的 key（前提：所有字段可比较）----------
	counts := map[Member]int{}
	counts[m] = 1
	counts[m.clone()] = 2 // clone 后 Tags 内容相同但底层数组不同，== 比较的是内容
	fmt.Printf("以 Member 作 map key: 共 %d 个条目（注意含 slice 的 struct 不能做 key，这行只因 Tags != nil 会被编译拒绝）\n", len(counts))

	// 换成可比较的类型做 key
	type IDOnly struct {
		ID int
	}
	idm := map[IDOnly]string{{1: "小林", 2: "小森"}[IDOnly{1}]: "小林", IDOnly{2}: "小森"}
	_ = idm
	fmt.Println("可比较的 struct（无 slice/map/func）可以作 map key")
	fmt.Println(time.Now().Format(time.RFC3339), "演示结束")
}

package main

import "fmt"

// ============ 类型一：Account，需要修改，统一用指针接收者 ============

type Account struct {
	ID       string
	Name     string
	Balance  int64 // 单位：分
	Log      []string
	settings map[string]string // 含 map，更不能用值接收者
}

func NewAccount(id, name string) *Account {
	// 返回指针：调用方拿到的就是同一个对象
	return &Account{
		ID: id, Name: name,
		settings: map[string]string{"owner": "小林"},
	}
}

func (a *Account) Deposit(amount int64) bool {
	if amount <= 0 {
		return false
	}
	a.Balance += amount
	a.Log = append(a.Log, fmt.Sprintf("存入 %d", amount))
	return true
}

func (a *Account) Withdraw(amount int64) error {
	if amount <= 0 {
		return fmt.Errorf("金额必须为正，收到 %d", amount)
	}
	if a.Balance < amount {
		return fmt.Errorf("余额不足：当前 %d 分，尝试取 %d 分", a.Balance, amount)
	}
	a.Balance -= amount
	a.Log = append(a.Log, fmt.Sprintf("取出 %d", amount))
	return true
}

// SetOwner 必须用指针接收者，否则改的是副本
func (a *Account) SetOwner(name string) {
	a.settings["owner"] = name
	a.Name = name
}

// 这个方法演示「静默失效」：值接收者 + 修改字段 = 编译通过但没用
func (a Account) BrokenReset() {
	a.Balance = 0        // 只改了副本！
	a.Name = "已重置"     // 同上
	a.Log = nil          // 同上
}

// 用值接收者做只读操作是安全且推荐的：省一次指针解引用，且 Account 和 *Account 都能用
func (a Account) Summary() string {
	return fmt.Sprintf("%s(%s) 余额 %d 分，共 %d 条记录", a.Name, a.ID, a.Balance, len(a.Log))
}

// ============ 类型二：Point，纯值且不可变，用值接收者 ============

type Point struct {
	X, Y int
}

func (p Point) Distance(o Point) int {
	dx, dy := p.X-o.X, p.Y-o.Y
	return dx*dx + dy*dy // 故意不开根号，只比较大小
}

func (p Point) String() string {
	return fmt.Sprintf("(%d,%d)", p.X, p.Y)
}

// 值类型 + 值接收者的方法，编译进二进制不引入额外依赖（后面零依赖优化会用到）
func (p Point) Norm2() int { return p.X*p.X + p.Y*p.Y }

// ============ 接口与隐式实现 ============

// Stringer：fmt 见到它就会自动调用 String() 格式化该值
type Stringer interface {
	String() string
}

// Teller：需要 Deposit 和 Withdraw 两个方法
type Teller interface {
	Deposit(amount int64) bool
	Withdraw(amount int64) error
	Summary() string
}

func main() {
	// ---- 1. 指针接收者：能改到本体 ----
	acc := NewAccount("acc_001", "小林")
	fmt.Println("初始:", acc.Summary())
	acc.Deposit(12345)
	acc.Deposit(5)
	fmt.Println("存入两笔后:", acc.Summary())
	fmt.Println("操作记录:", acc.Log)

	// ---- 2. 错误处理：Withdraw 返回 error ----
	if err := acc.Withdraw(99999); err != nil {
		fmt.Println("取出失败:", err)
	}
	if err := acc.Withdraw(300); err != nil {
		fmt.Println("不该走到这里:", err)
	} else {
		fmt.Println("取出成功:", acc.Summary())
	}

	// ---- 3. SetOwner 通过指针生效 ----
	acc.SetOwner("小森")
	fmt.Printf("改 owner 后: name=%q settings=%v\n", acc.Name, acc.settings)

	// ---- 4. 静默失效：编译通过，什么也没发生 ----
	before := acc.Summary()
	acc.BrokenReset()
	fmt.Printf("BrokenReset 前: %s\n", before)
	fmt.Printf("BrokenReset 后: %s   ← 完全没变！因为用的是值接收者\n", acc.Summary())

	// 对照：手动用值调用一个指针接收者方法，Go 会帮你取地址
	// （但反过来不行：指针调用值接收者方法是允许的）
	v := *acc  // 显式拷贝一份
	v.Deposit(100)
	fmt.Printf("拷贝体 v.Deposit 后: v=%s  原 acc=%s   ← 原的没变\n", v.Summary(), acc.Summary())

	// ---- 5. 值接收者的纯值类型 ----
	p1 := Point{3, 4}
	p2 := Point{0, 0}
	fmt.Printf("%v 到 %v 的距离平方: %d\n", p1, p2, p1.Distance(p2))
	fmt.Printf("p1=%s p1.Norm2=%d\n", p1, p1.Norm2())

	// p1 满足 Stringer（值接收者），*p1 也满足
	var s Stringer = p1
	fmt.Printf("p1 满足 Stringer: %s\n", s)

	// ---- 6. 方法集：*Account 满足 Teller，Account 不满足 ----
	var t Teller = acc // *Account 有 Deposit/Withdraw（指针）+ Summary（值）
	fmt.Printf("*Account 满足 Teller: %s\n", t.Summary())

	// 下面这行编译不过，解注释看报错：
	// var t2 Teller = *acc
	// cannot use *acc (value of type Account) as Teller value in assignment:
	// Account does not implement Teller (missing method Deposit
	//   have Deposit() bool  want Deposit(amount int64) bool)
	//
	// 原因：Account 的方法集里只有值接收者的 Summary，
	//       Deposit/Withdraw 是指针接收者的，不在 Account 的方法集里
	fmt.Println("↑ 注释里是「值类型不能满足以指针方法为核心的接口」的证据")

	// ---- 7. 嵌入 + 方法提升：让 Account 也能满足 Teller？----
	// 不行。除非改成值接收者，但那会破坏修改能力。
	// 正确的做法永远是传 *Account。见 S1 D6 之后的服务层封装。
}

// jf —— JSON 格式化命令行工具（W3 收口产出）
//
// 用法：
//   echo '{"b":2,"a":1}' | go run ./lab/s1/d06/jf
//   jf -i "    " data.json          指定缩进
//   jf -o out.json data.json       写入文件
//   jf -compact data.json          压缩成一行
//   jf -sort data.json             先按 key 排序再格式化
//
// 本工具用到的 W3 知识：
//   package main / os.Args          —— 包与进程入口
//   flag                             —— 标准库参数解析
//   struct tag `json:...`           —— D4 的序列化控制
//   指针接收者 + *int 可选值          —— D5 + D6
//   显式类型转换 interface{}         —— D3
//   := 与零值、错误处理               —— D2

package main

import (
	"bytes"
	"encoding/json"
	"errors"
	"flag"
	"fmt"
	"io"
	"os"
	"sort"
	"strings"
)

const version = "jf 1.0.0"

// Options 是配置结构体。用指针接收者，因为它要被 flag 填充后使用。
type Options struct {
	Indent  string // 缩进字符串，默认两个空格
	Output  string // 输出文件，空则写 stdout
	Compact bool   // 压缩成一行
	Sort    bool   // 按 key 排序
	Tab     bool   // 用 Tab 代替空格缩进
}

func (o *Options) indentString() string {
	if o.Tab {
		return "\t"
	}
	return o.Indent
}

// ErrEmptyInput 是自定义错误。errors.New 创建，fmt.Errorf 包装。
var ErrEmptyInput = errors.New("输入为空，没有可格式化的 JSON")

// readInput 决定数据来源：文件参数优先，否则读 stdin
func readInput() ([]byte, error) {
	// os.Args[0] 是程序名，os.Args[1:] 才是真正的参数
	args := os.Args[1:]
	// 找第一个不以 - 开头的参数，那就是文件路径
	var path string
	for _, a := range args {
		if !strings.HasPrefix(a, "-") {
			path = a
			break
		}
	}

	if path == "" {
		// stdin 是 *os.File 类型的一个值，赋给 io.Reader 接口变量
		var r io.Reader = os.Stdin
		stat, _ := os.Stdin.Stat()
		// 检测是否管道输入：(stat.Mode() & os.ModeCharDevice) == 0
		if stat != nil && (stat.Mode()&os.ModeCharDevice) == 0 {
			data, err := io.ReadAll(r)
			if err != nil {
				return nil, fmt.Errorf("读取 stdin 失败: %w", err)
			}
			if len(bytes.TrimSpace(data)) == 0 {
				return nil, ErrEmptyInput
			}
			return data, nil
		}
		return nil, fmt.Errorf("请提供文件路径，或用管道传入 JSON（用法见 %s）", version)
	}

	data, err := os.ReadFile(path)
	if err != nil {
		// %w 包装底层错误，调用方可以用 errors.Is 判断原因
		return nil, fmt.Errorf("读取文件 %s 失败: %w", path, err)
	}
	if len(bytes.TrimSpace(data)) == 0 {
		return nil, fmt.Errorf("%w（文件 %s）", ErrEmptyInput, path)
	}
	return data, nil
}

// format 是核心逻辑：验证 → （可选）排序 → 格式化
func format(data []byte, opt *Options) ([]byte, error) {
	// 先用 json.Valid 快速判断，避免后面拿到没意义的报错
	if !json.Valid(data) {
		return nil, fmt.Errorf("不是合法 JSON")
	}

	var buf bytes.Buffer

	if opt.Compact {
		// Compact 去掉所有多余空白，压成一行
		if err := json.Compact(&buf, data); err != nil {
			return nil, fmt.Errorf("压缩失败: %w", err)
		}
	} else {
		// 排序：先反序列化到 map[string]interface{}
		// 注意：map 会让 key 顺序丢失，所以必须重新序列化
		if opt.Sort {
			var obj map[string]interface{}
			if err := json.Unmarshal(data, &obj); err != nil {
				return nil, fmt.Errorf("解析失败: %w", err)
			}
			sorted, err := sortObject(obj)
			if err != nil {
				return nil, err
			}
			data, _ = json.Marshal(sorted) // Marshal 对 map 的 key 会自动排序
		}
		// Indent 做真正的缩进格式化
		if err := json.Indent(&buf, data, "", opt.indentString()); err != nil {
			return nil, fmt.Errorf("格式化失败: %w", err)
		}
	}

	buf.WriteByte('\n') // 结尾加换行，命令行输出习惯
	return buf.Bytes(), nil
}

// sortObject 递归排序（其实 encoding/json 的 Marshal 已经会对 map 排序，
// 这里保留是为了展示「嵌套 map 也能处理」的结构）
func sortObject(obj map[string]interface{}) (map[string]interface{}, error) {
	out := make(map[string]interface{}, len(obj))
	for k, v := range obj {
		if nested, ok := v.(map[string]interface{}); ok {
			sorted, err := sortObject(nested)
			if err != nil {
				return nil, err
			}
			out[k] = sorted
			continue
		}
		out[k] = v
	}
	// 确保真的按 key 排序输出（marshal 前的防御性处理）
	keys := make([]string, 0, len(out))
	for k := range out {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	return out, nil
}

// run 是真正干活的函数，返回退出码，方便测试
func run(argv []string, stdout io.Writer) int {
	fs := flag.NewFlagSet("jf", flag.ContinueOnError)
	fs.SetOutput(os.Stderr)

	var opt Options
	fs.StringVar(&opt.Indent, "i", "  ", "缩进字符串（默认两个空格）")
	fs.StringVar(&opt.Output, "o", "", "输出文件（默认标准输出）")
	fs.BoolVar(&opt.Compact, "compact", false, "压缩成一行")
	fs.BoolVar(&opt.Sort, "sort", false, "按 key 排序")
	fs.BoolVar(&opt.Tab, "tab", false, "用 Tab 缩进")

	if err := fs.Parse(argv); err != nil {
		return 2 // flag 解析错误的标准退出码
	}

	data, err := readInput()
	if err != nil {
		// 区分「用法错误」和「数据错误」用退出码：2 是用法，1 是数据
		if errors.Is(err, ErrEmptyInput) {
			fmt.Fprintln(os.Stderr, "错误:", err)
			return 1
		}
		fmt.Fprintf(os.Stderr, "%s: %v\n", version, err)
		return 1
	}

	out, err := format(data, &opt)
	if err != nil {
		fmt.Fprintf(os.Stderr, "%s: %v\n", version, err)
		return 1
	}

	if opt.Output == "" {
		stdout.Write(out)
		return 0
	}
	if err := os.WriteFile(opt.Output, out, 0o644); err != nil {
		fmt.Fprintf(os.Stderr, "写入 %s 失败: %v\n", opt.Output, err)
		return 1
	}
	fmt.Fprintf(os.Stderr, "已写入 %s（%d 字节）\n", opt.Output, len(out))
	return 0
}

func main() {
	// 去掉程序名，os.Args[0]
	os.Exit(run(os.Args[1:], os.Stdout))
}

