package main

import "fmt"

// dump 把 slice 的三件套一次性打出来，后面所有例子都用它观察变化
func dump(tag string, s []int) {
	fmt.Printf("%s: len=%d cap=%d 值=%v\n", tag, len(s), cap(s), s)
}

func main() {
	// ---- 1. 三种创建方式 ----
	var s1 []int            // 零值：nil slice，len=cap=0
	s2 := []int{1, 2, 3}    // 字面量：len=cap=3
	s3 := make([]int, 2, 4) // 显式 len=2 cap=4，超出 len 的部分是零值但不可见

	dump("s1(nil)", s1)
	dump("s2(字面量)", s2)
	dump("s3(make)", s3)

	s3[0], s3[1] = 10, 20
	dump("s3 赋值后", s3)

	// ---- 2. 切片表达式：只挪窗口，不复制元素 ----
	a := []int{0, 1, 2, 3, 4, 5}
	dump("a 本身", a)
	dump("a[1:3]", a[1:3])
	dump("a[2:]", a[2:])
	dump("a[:2]", a[:2])
	dump("a[:]", a[:])
	// 规则：len = high - low，cap = cap(a) - low
	fmt.Printf("三索引 a[1:3:4]: len=%d cap=%d 值=%v\n", len(a[1:3:4]), cap(a[1:3:4]), a[1:3:4])

	// ---- 3. append：cap 内原地写，超出 cap 换新数组并复制 ----
	g := make([]int, 2, 4)
	before := cap(g)
	g = append(g, 30, 40) // len 2 -> 4，正好用满 cap，没有扩容
	fmt.Printf("cap 够用：append 前 cap=%d，append 后 len=%d cap=%d\n", before, len(g), cap(g))

	g = append(g, 50) // len=4 cap=4 装不下，必须扩容
	// 扩容倍数是实现细节（当前是小于 256 时翻倍），所以只断言下界
	fmt.Printf("cap 不够：append 后 len=%d，cap 至少 5 吗? %v\n", len(g), cap(g) >= 5)

	// 扩容会把老元素复制到新数组，所以老切片头依然指着那块已经没人再用的内存
	full := make([]int, 2, 2) // 故意让 cap == len
	keep := full              // keep 和 full 是两份独立的三件套，指向同一块数组
	full = append(full, 99)   // 必然扩容
	fmt.Printf("full=%v  keep=%v  ← keep 还指着扩容前那块数组\n", full, keep)

	// ---- 4. nil slice 的能力边界 ----
	var ns []int
	fmt.Printf("nil slice: len=%d cap=%d，range 次数恒为 0\n", len(ns), cap(ns))
	ns = append(ns, 7) // 安全：append 发现没地方放，会分配一块新数组
	fmt.Printf("nil slice append 后: %v  nil? %v\n", ns, ns == nil)
	// ns[0] = 1     ← 取消注释：panic: runtime error: index out of range [0] with length 1
	// fmt.Println(ns[0]) ← 越界，报的是 index out of range，不是空指针

	// ---- 5. 想要真正独立的一份，必须显式复制 ----
	shared := []int{1, 2, 3}
	alias := shared // 两个切片头指向同一块数组
	alias[0] = 100
	fmt.Println("改 alias 后 shared =", shared, " ← 被影响了")

	own := make([]int, len(shared))
	copy(own, shared) // copy 是值拷贝的标准做法
	own[0] = 200
	fmt.Println("copy 后 shared =", shared, " own =", own)
}

package main

import "fmt"

type Task struct {
	ID   int
	Name string
}

// ---- 坑一：子切片与原数组共享底层数据 ----

// badFilter 返回 a 的一个子集，但没有隔离共享
func badFilter(a []int, keep func(int) bool) []int {
	out := []int{}
	for _, v := range a {
		if keep(v) {
			out = append(out, v)
		}
	}
	return out
}

// goodFilter 用三索引把返回值的 cap 钉死：调用方随便 append 都不会碰 a 的隐藏区域
func goodFilter(a []int, keep func(int) bool) []int {
	var out []int
	for i, v := range a {
		if keep(v) {
			out = append(out, a[i:i+1:i+1]...) // a[i:i+1:i+1] 的 cap=1，append 必然扩容
		}
	}
	return out
}

func main() {
	// ---- 坑一 ----
	a := []int{1, 2, 3, 4, 5, 6}
	sub := a[1:4]
	fmt.Printf("sub 切片 = %v（len=%d cap=%d）\n", sub, len(sub), cap(sub))
	sub[0] = 99
	fmt.Printf("改 sub[0]=99 后 a = %v  ← 共享同一块底层数组\n", a)

	// 用 clear 恢复，方便后面观察（clear 是 Go 1.21 起的内置函数，把元素置零值，不改 len）
	clear(a)
	a[0], a[1], a[2], a[3], a[4], a[5] = 1, 2, 3, 4, 5, 6

	// badFilter 返回的 out 和 a 完全无关（因为 append 扩容了），
	// 但一旦 out 的 cap 恰好够，就会写进 a 的隐藏区域。这里先看它其实没共享：
	bad := badFilter(a, func(v int) bool { return v%2 == 0 })
	fmt.Printf("badFilter 结果 = %v，a 仍是 %v\n", bad, a)

	// 直接构造共享场景：q 和 a 指向同一块数组
	q := []int{10, 20, 30, 40, 50}
	view := q[1:3]
	fmt.Printf("view = %v\n", view)
	view = append(view, 777) // view 的 cap = cap(q)-1 = 4，len=2，所以还有空间 → 原地写
	fmt.Printf("append 后 view = %v，q = %v  ← q[3] 从 40 变成了 777，这就是「看不见的写」\n", view, q)

	// ---- 坑二：range 取地址 ----
	tasks := []Task{{1, "写文档"}, {2, "写测试"}, {3, "部署"}}
	var ptrs []*Task
	for _, v := range tasks {
		ptrs = append(ptrs, &v) // go.mod 的 go >= 1.22 时安全；< 1.22 时三个指针全是最后一个
	}
	fmt.Printf("Go 1.22 语义下 &v 拿到: %s / %s / %s\n", ptrs[0].Name, ptrs[1].Name, ptrs[2].Name)

	// 不依赖语言版本的稳妥写法：显式取元素地址
	var ptrs2 []*Task
	for i := range tasks {
		ptrs2 = append(ptrs2, &tasks[i])
	}
	fmt.Printf("&tasks[i] 拿到:        %s / %s / %s\n", ptrs2[0].Name, ptrs2[1].Name, ptrs2[2].Name)

	// ---- 坑三：append 覆盖 ----
	base := make([]int, 3, 10) // 故意留大 cap
	base[0], base[1], base[2] = 1, 2, 3
	left := base[:2]            // len=2 cap=10
	right := base[2:3]          // len=1 cap=8，从下标 2 开始

	left = append(left, 555) // 还有 cap，原地写在 base 的下标 2 处
	fmt.Printf("left append 之后 left=%v base=%v  ← base[2] 被覆盖了\n", left, base)

	clear(base)
	base[0], base[1], base[2] = 1, 2, 3
	right = append(right, 888) // 起点在 base 的下标 2，写的是下标 3（在 base 的 len 之外、cap 之内）
	fmt.Printf("right append 之后 right=%v base=%v  ← base 的隐藏区域被写了，遍历 len 看不见它\n", right, base)
	// 这就是为什么 base 之后如果有人扩到 len=4，会突然「冒出」一个 888

	// ---- 正确姿势对照 ----
	src := []int{1, 2, 3, 4, 5}
	cp := make([]int, len(src))
	copy(cp, src)
	cp[0] = -1
	fmt.Printf("copy 后 src=%v cp=%v  ← 完全独立\n", src, cp)

	tail := src[2:5:5] // 三索引：len=3 cap=3
	tail = append(tail, 100) // cap 用尽 → 必然扩容
	fmt.Printf("三索引 tail=%v src=%v  ← src 干干净净\n", tail, src)
}

package main

import (
	"fmt"
	"sort"
)

type Member struct {
	Name    string
	Role    string // owner/admin/member
	Score   int
	Joined  int // 加入序号，用于观察稳定性
}

// ---- 构造二维切片的两种方式 ----

// newMatrix 演示「只 make 外层」是不够的
func newMatrixBroken(rows, cols int) [][]int {
	m := make([][]int, rows) // 只有外层有长度，内层全是 nil slice
	return m
}

func newMatrixOK(rows, cols int) [][]int {
	m := make([][]int, rows)
	for i := range m {
		m[i] = make([]int, cols) // 每一行都要单独分配
	}
	return m
}

func identity(n int) [][]int {
	// 字面量写法：编译器为每行单独分配，最直观
	m := make([][]int, n)
	for i := range m {
		for j := range m[i] {
			m[i][j] = i*n + j
		}
	}
	return m
}

func transpose(m [][]int) [][]int {
	if len(m) == 0 {
		return nil
	}
	out := make([][]int, len(m[0]))
	for i := range out {
		out[i] = make([]int, len(m))
		for j := range m {
			out[i][j] = m[j][i]
		}
	}
	return out
}

func flatten(m [][]int) []int {
	var out []int
	for _, row := range m {
		out = append(out, row...)
	}
	return out
}

func main() {
	// ---- 1. 构造：必须逐行分配 ----
	broken := newMatrixBroken(2, 3)
	fmt.Printf("只 make 外层: len(外层)=%d, 第 0 行 == nil? %v\n", len(broken), broken[0] == nil)
	// broken[0][0] = 1  ← 取消注释：panic: runtime error: index out of range [0] with length 0

	ok := newMatrixOK(2, 3)
	ok[0][0], ok[0][2], ok[1][1] = 1, 3, 6
	fmt.Printf("逐行 make: %v\n", ok)

	// ---- 2. 遍历的两种写法 ----
	m := identity(3)
	fmt.Printf("3x3 恒等矩阵: %v\n", m)

	sumA := 0
	for i := range m { // 写法一：要下标
		for j := range m[i] {
			sumA += m[i][j]
		}
	}
	sumB := 0
	for _, row := range m { // 写法二：不要下标
		for _, v := range row {
			sumB += v
		}
	}
	fmt.Printf("两种遍历求和: %d / %d（相等说明行为一致）\n", sumA, sumB)

	t := transpose(m)
	fmt.Printf("转置后:\n")
	for _, row := range t {
		fmt.Printf("  %v\n", row)
	}

	flat := flatten(m)
	fmt.Printf("拉平成一维: %v\n", flat)

	// ---- 3. 结构体切片排序 ----
	members := []Member{
		{"小林", "member", 70, 1},
		{"小森", "owner", 90, 2},
		{"小兰", "member", 90, 3},
		{"小谷", "admin", 70, 4},
	}

	byScore := make([]Member, len(members))
	copy(byScore, members)
	sort.Slice(byScore, func(i, j int) bool {
		return byScore[i].Score > byScore[j].Score // 分数高的在前
	})
	// sort.Slice 不稳定：同分元素的先后不保证，所以只断言「分数序列」是确定的
	fmt.Println("按分数降序（sort.Slice 不保证同分顺序）:")
	fmt.Print("  分数序列: ")
	for _, m := range byScore {
		fmt.Printf("%d ", m.Score)
	}
	fmt.Println()

	// ---- 4. 稳定排序：同分保持原顺序 ----
	stable := make([]Member, len(members))
	copy(stable, members)
	sort.SliceStable(stable, func(i, j int) bool {
		return stable[i].Score > stable[j].Score
	})
	fmt.Println("按分数降序（SliceStable 保证同分保持原顺序）:")
	for _, m := range stable {
		fmt.Printf("  %s/%s/%d/加入序号=%d\n", m.Name, m.Role, m.Score, m.Joined)
	}

	// ---- 5. 多字段排序：先按角色优先级，再按分数 ----
	roleRank := map[string]int{"owner": 0, "admin": 1, "member": 2}
	ranked := make([]Member, len(members))
	copy(ranked, members)
	sort.Slice(ranked, func(i, j int) bool {
		ri, rj := roleRank[ranked[i].Role], roleRank[ranked[j].Role]
		if ri != rj {
			return ri < rj
		}
		return ranked[i].Score > ranked[j].Score
	})
	fmt.Println("先角色后分数:")
	for _, m := range ranked {
		fmt.Printf("  %s(%s) %d\n", m.Name, m.Role, m.Score)
	}

	// ---- 6. 原地排序会影响所有共享底层数组的切片 ----
	shared := make([]Member, len(members))
	copy(shared, members)
	view := shared[1:3] // 共享 shared 的底层数组
	sort.SliceStable(shared, func(i, j int) bool { return shared[i].Score < shared[j].Score })
	fmt.Printf("排序 shared 之后 view 看到: ")
	for _, m := range view {
		fmt.Printf("%s ", m.Name)
	}
	fmt.Println("← view 也被重排了，尽管它的 len 只有 2")
}

package main

import (
	"fmt"
	"sort"
)

type User struct {
	Name string
	Age  int
}

// ---- nil map：读安全，写 panic ----

var nilUsers map[string]int // 包级 nil map

func main() {
	// ---- 1. 三种创建方式 ----
	byName := map[string]User{"小林": {"小林", 30}} // 字面量
	byAge := make(map[string]int)                  // make
	byAge["young"] = 1
	pre := make(map[string]int, 100) // 第二个参数是预分配的桶数，纯性能提示
	pre["a"] = 1

	fmt.Printf("字面量: %v\n", byName)
	fmt.Printf("make:    %v\n", byAge)
	fmt.Printf("预分配 len=%d\n", len(pre))

	// ---- 2. nil map 的能力边界 ----
	fmt.Printf("nil map: len=%d, 读不存在的键=%d, nil?=%v\n", len(nilUsers), nilUsers["x"], nilUsers == nil)
	fmt.Printf("nil map range 次数=%d\n", len(nilUsers))
	// nilUsers["x"] = 1 ← 取消注释：panic: assignment to entry in nil map

	// ---- 3. comma-ok：区分不存在与零值 ----
	scores := map[string]int{"小林": 90, "小谷": 0}
	v1, ok1 := scores["小林"]
	fmt.Printf("查存在的键: 值=%d ok=%v\n", v1, ok1)
	v2, ok2 := scores["小谷"]
	fmt.Printf("查值为0的键: 值=%d ok=%v  ← 用值判断会误判\n", v2, ok2)
	v3, ok3 := scores["不存在"]
	fmt.Printf("查不存在的键: 值=%d ok=%v\n", v3, ok3)

	// 简化写法：只关心存在性
	if _, ok := scores["不存在"]; !ok {
		fmt.Println("用 _, ok 判定：确实不存在")
	}

	// map[string]bool 可以直接用值判断，因为 false 语义上等价于不存在
	flags := map[string]bool{"on": true}
	if flags["off"] {
		fmt.Println("不会打印")
	} else {
		fmt.Println("bool map 可以直接用值判断")
	}

	// ---- 4. 遍历顺序：不保证，所以先排序键 ----
	word := map[string]int{"alpha": 1, "beta": 2, "gamma": 3, "delta": 4}

	// 原始 range 的顺序未指定，所以只收集不打印；顺序问题在 step 里用 10 次运行验证
	raw := make([]string, 0, len(word))
	for k, v := range word {
		raw = append(raw, fmt.Sprintf("%s=%d", k, v))
	}
	fmt.Printf("原始 range 拿到 %d 个条目（顺序每次可能不同，故不打印内容）\n", len(raw))

	keys := make([]string, 0, len(word))
	for k := range word {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	// sort.Strings 按字节序比较：E5898D(前) < E5908E(后) < E8BF90(运)
	fmt.Println("--- 排序键之后遍历（稳定）---")
	for _, k := range keys {
		fmt.Printf("  %s=%d\n", k, word[k])
	}

	// ---- 5. delete 与「range 中不能删除」----
	fmt.Printf("删除前 len=%d\n", len(word))
	delete(word, "beta")
	delete(word, "不存在的键") // 安全空操作
	fmt.Printf("删除后 len=%d，beta还在? %v\n", len(word), func() bool { _, ok := word["beta"]; return ok }())

	// 错误写法演示（注释掉）：range 中删除会 panic 或行为未定义
	// for k := range word { delete(word, k) }

	// 正确写法：先收集，range 结束后删
	old := map[string]int{"a": 1, "b": 2, "c": 3, "d": 4}
	var toDelete []string
	for k := range old {
		if old[k]%2 == 0 {
			toDelete = append(toDelete, k)
		}
	}
	for _, k := range toDelete {
		delete(old, k)
	}
	fmt.Printf("删除偶数值后: %v\n", old)

	// ---- 6. 键的类型：可比较性 ----
	// 不能用 slice 当键：
	// m := map[[]string]bool{}  ← invalid map key type []string
	// 替代方案：规范化的字符串
	seen := map[string]bool{}
	for _, tag := range []string{"go", "sql", "go"} {
		seen[strings_JoinForDemo(tag)] = true
	}
	fmt.Printf("set 大小=%d（用字符串键模拟 slice 的 set）\n", len(seen))

	// 结构体键：字段都可比较时可以做键
	type Point struct{ X, Y int }
	visited := map[Point]bool{{1, 2}: true, {3, 4}: true}
	visited[Point{1, 2}] = true // 覆盖已有的
	fmt.Printf("结构体键 set 大小=%d\n", len(visited))

	// ---- 7. map 的常见用法：分组与索引 ----
	members := []struct {
		Name string
		Team string
	}{{"小林", "后端"}, {"小森", "前端"}, {"小兰", "后端"}, {"小谷", "运维"}}

	groups := map[string][]string{} // 值是 slice：追加到已有键时不会互相干扰
	for _, m := range members {
		groups[m.Team] = append(groups[m.Team], m.Name)
	}
	teams := make([]string, 0, len(groups))
	for t := range groups {
		teams = append(teams, t)
	}
	sort.Strings(teams)
	for _, t := range teams {
		fmt.Printf("  %s: %v\n", t, groups[t])
	}
}

// strings_JoinForDemo 演示用：把单元素 tag 当作规范的字符串键
// 真实代码里如果 key 是多元素 slice，要用 strings.Join(tag, "|") 保证不碰撞
func strings_JoinForDemo(tag string) string { return "tag:" + tag }

package main

import (
	"fmt"
	"strings"
	"unicode"
	"unicode/utf8"
)

func main() {
	s := "Hello小林😀"

	// ---- 1. len 是字节数 ----
	fmt.Printf("字符串: %q\n", s)
	fmt.Printf("len(s) = %d（字节数）\n", len(s))
	fmt.Printf("utf8.RuneCountInString(s) = %d（字符数）\n", utf8.RuneCountInString(s))
	fmt.Printf("len(\"abc\")=%d len(\"小林\")=%d len(\"😀\")=%d\n", len("abc"), len("小林"), len("😀"))

	// ---- 2. s[i] 是字节，[]rune(s)[i] 是字符 ----
	fmt.Printf("s[0] = %d (byte 'H')\n", s[0])
	fmt.Printf("s[5] = %#x（小林的第一个字节，不是字符）\n", s[5])
	rs := []rune(s)
	fmt.Printf("[]rune(s) 长度=%d，rs[0]=%q rs[5]=%q rs[6]=%q\n", len(rs), rs[0], rs[5], rs[6])
	bs := []byte(s)
	fmt.Printf("[]byte(s) 长度=%d，bs[0]=%d\n", len(bs), bs[0])

	// 往返转换无损
	fmt.Printf("[]rune 转回字符串 == 原串? %v\n", string(rs) == s)

	// ---- 3. range 字符串：字节偏移 + rune ----
	for i, r := range "小林ok" {
		fmt.Printf("  偏移=%d 码点=%#x 字符=%c\n", i, r, r)
	}
	fmt.Println("  注意偏移是 0,3,6,7 —— 0/3 是中文字节，6/7 是 ASCII")

	// 只要字符不要偏移
	idx := 0
	for _, r := range "小林ok" {
		fmt.Printf("  字符下标=%d 字符=%c\n", idx, r)
		idx++
	}

	// ---- 4. rune 是 int32，可以直接做字符运算与比较 ----
	fmt.Printf("'A'=%d '小'=%d '小'-'A'=%d\n", 'A', '小', '小'-'A')
	fmt.Printf("IsLetter(小)=%v IsDigit(7)=%v IsSpace(全角空格 U+3000)=%v\n",
		unicode.IsLetter('小'), unicode.IsDigit('7'), unicode.IsSpace('\u3000'))

	// ---- 5. 中文安全截断 ----
	long := "这是一个很长的中文备注，需要被截断"
	runes := []rune(long)
	if len(runes) > 10 {
		long = string(runes[:10]) + "…"
	}
	fmt.Printf("按字符截断: %s（rune 数=%d）\n", long, utf8.RuneCountInString(long))

	// 错误演示：按字节截断会切出半个字符，%q 能把那个半个字节显成 \xNN
	broken := "这是一个很长的中文备注"[:10]
	fmt.Printf("按字节截断: %q 字节=%d 字符数=%d ← 切出了半个「个」字\n", broken, len(broken), utf8.RuneCountInString(broken))

	// ---- 6. strings 常用函数 ----
	line := "  GET /api/members?limit=20&cursor=abc  "
	fields := strings.Fields(line) // 按任意空白切分
	fmt.Printf("Fields 切分 %d 段: %v\n", len(fields), fields)
	fmt.Printf("TrimSpace: %q\n", strings.TrimSpace(line))

	// Cut 在第一个分隔符处切成两段
	before, after, found := strings.Cut(line, "?")
	fmt.Printf("Cut: before=%q after=%q found=%v\n", strings.TrimSpace(before), after, found)

	// 前缀判断
	fmt.Printf("HasPrefix(%q, \"  GET\")=%v  TrimSpace 后=%v\n", line, strings.HasPrefix(line, "  GET"), strings.HasPrefix(strings.TrimSpace(line), "GET"))

	// 大小写不敏感比较：EqualFold 比 ToLower 两遍更高效
	fmt.Printf("EqualFold(\"HomeCube\", \"homecube\")=%v\n", strings.EqualFold("HomeCube", "homecube"))

	// 替换与重复
	fmt.Printf("ReplaceAll: %s\n", strings.ReplaceAll("a-b-c", "-", "_"))
	fmt.Printf("Repeat: %q\n", strings.Repeat("=", 10))

	// ---- 7. strings.Builder：循环里拼字符串的正确工具 ----
	parts := []string{"小林", "小森", "小兰"}
	var sb strings.Builder
	sb.WriteString("成员: ")
	for i, p := range parts {
		if i > 0 {
			sb.WriteString(", ")
		}
		fmt.Fprintf(&sb, "%s(%d字)", p, utf8.RuneCountInString(p))
	}
	sb.WriteString("\n")
	fmt.Print(sb.String())

	// 对比：+= 在循环里每次都可能重新分配
	s2 := ""
	for _, p := range parts {
		s2 += p
	}
	fmt.Printf("+= 拼接结果相同? %v\n", s2 == "小林小森小兰")

	// ---- 8. 校验：中文字符长度检查的正确写法 ----
	name := "小"
	fmt.Printf("\"小\" 字节长度=%d，字符长度=%d，utf8.RuneCountInString=%d\n", len(name), len([]rune(name)), utf8.RuneCountInString(name))
	fmt.Printf("能否通过「最多 1 个字符」校验? %v\n", utf8.RuneCountInString(name) <= 1)
}

package main

import (
	"encoding/json"
	"errors"
	"fmt"
	"strconv"
	"strings"
	"time"
)

// ---- DTO：所有对外的 JSON 结构体都要写完整 tag ----

type MemberDTO struct {
	ID      string    `json:"id"`
	Name    string    `json:"name"`
	Age     int       `json:"age"`
	Active  bool      `json:"active"`            // 不加 omitempty：false 也要输出
	Role    string    `json:"role,omitempty"`   // 空字符串才省略
	Score   int       `json:"score,omitempty"`  // ⚠️ 0 也会被省略
	Tags    []string  `json:"tags,omitempty"`   // 空切片也会被省略
	Created time.Time `json:"created_at"`       // 时间的序列化
	Note    string    `json:"-"`                // 不参与序列化
	private int                                  // 小写字段不参与
}

func main() {
	// ---- 1. fmt 的动词 ----
	n := 42
	ratio := 0.123456
	fmt.Printf("%%v=%v %%+v=%+v %%T=%T\n", n, n, n)
	fmt.Printf("%%d=%d %%x=%x %%c=%c %%o=%o\n", n, n, 65, n)
	fmt.Printf("%%.2f=%.2f 左对齐=[%-5s]\n", ratio, "ab")
	fmt.Printf("%%q=%q %%t=%t\n", "带\"引号\"\n的串", true)
	// 注意：%p 打印内存地址，每次运行都不同，所以本示例不用它做断言

	// 多个参数复用一个动词：%v 会按参数个数展开
	count, total := 3, 100
	fmt.Printf("%%v 展开: %v\n", count, total)
	fmt.Printf("%%d 展开: %d\n", count, total)

	// 把格式化结果转成 error 类型（fmt.Errorf + %s）
	e := fmt.Errorf("解析 %q 失败: 期望整数，得到 %s", "abc", "\"abc\"")
	fmt.Println("错误信息:", e)

	// ---- 2. strconv：数字与字符串 ----
	i, err := strconv.Atoi("123")
	fmt.Printf("Atoi(\"123\") = %d, err=%v\n", i, err)
	i2, err2 := strconv.Atoi("12x")
	fmt.Printf("Atoi(\"12x\") = %d, err=%v  ← 解析失败返回零值 + 错误\n", i2, err2)
	hex, _ := strconv.ParseInt("1f", 16, 64)
	auto, _ := strconv.ParseInt("0x1f", 0, 64) // base=0 按前缀自动判断
	f, _ := strconv.ParseFloat("3.14159", 64)
	f32, _ := strconv.ParseFloat("3.14159", 32) // 32 位精度会损失
	fmt.Printf("ParseInt 16进制=%d 自动进制=%d\n", hex, auto)
	fmt.Printf("ParseFloat 64位=%.9f 32位=%.9f  ← 32 位已经失真\n", f, f32)
	fmt.Printf("Itoa(99)=%q FormatFloat=%.2f\n", strconv.Itoa(99), 99.0)
	fmt.Printf("Quote=%s\n", strconv.Quote(`他说"你好"`))

	// 解析 + 校验的惯用法
	parseLimit := func(s string) (int, error) {
		n, err := strconv.Atoi(s)
		if err != nil {
			return 0, fmt.Errorf("limit 参数非法: %w", err)
		}
		if n <= 0 || n > 100 {
			return 0, errors.New("limit 必须在 1..100 之间")
		}
		return n, nil
	}
	for _, s := range []string{"20", "abc", "500"} {
		v, err := parseLimit(s)
		if err != nil {
			fmt.Printf("parseLimit(%q) 失败: %v\n", s, err)
		} else {
			fmt.Printf("parseLimit(%q) = %d\n", s, v)
		}
	}

	// ---- 3. JSON 序列化：默认字段名 vs tag ----
	now := time.Date(2026, 10, 15, 10, 30, 0, 0, time.FixedZone("CST", 8*3600))
	bad := struct {
		Name string // 没有 tag
		Age  int
	}{"小林", 30}
	b, _ := json.Marshal(bad)
	fmt.Println("没有 tag 时:", string(b)) // 字段名是 PascalCase！

	good := MemberDTO{
		ID: "m_001", Name: "小林", Age: 30, Active: true,
		Role: "owner", Score: 0, Tags: nil,
		Created: now, Note: "不会出现在 JSON 里",
	}
	b2, _ := json.Marshal(good)
	fmt.Println("有 tag 时:  ", string(b2))
	fmt.Println("  ↑ Score=0 因为 omitempty 被省略了；Active=true 保留")

	// MarshalIndent：格式化输出
	b3, _ := json.MarshalIndent(good, "", "  ")
	fmt.Println("格式化:\n" + string(b3))

	// ---- 4. JSON 反序列化与未知字段 ----
	payload := []byte(`{"id":"m_002","name":"小森","age":31,"active":false,"role":"admin","score":88,"created_at":"2026-10-15T02:30:00Z"}`)
	var m MemberDTO
	if err := json.Unmarshal(payload, &m); err != nil {
		fmt.Println("解析失败:", err)
		return
	}
	fmt.Printf("解析结果: id=%s name=%s age=%d active=%v score=%d\n", m.ID, m.Name, m.Age, m.Active, m.Score)
	fmt.Printf("时间: %v  时区偏移=%v  IsZero=%v\n", m.Created, m.Created.Format("-07:00"), m.Created.IsZero())

	// ⚠️ 未知字段被静默忽略
	var m2 MemberDTO
	errUnknown := json.Unmarshal([]byte(`{"nmae":"拼错了","age":99}`), &m2)
	fmt.Printf("字段名拼错时 err=%v，解析出的 Name=%q Age=%d  ← 静默失败\n", errUnknown, m2.Name, m2.Age)

	// 解法一：严格模式
	dec := json.NewDecoder(strings.NewReader(`{"nmae":"x","age":99}`))
	dec.DisallowUnknownFields()
	var m3 MemberDTO
	fmt.Println("严格模式的报错:", dec.Decode(&m3))

	// 解法二：解析后校验必填字段
	var m4 MemberDTO
	json.Unmarshal([]byte(`{"age":99}`), &m4)
	if m4.ID == "" || m4.Name == "" {
		fmt.Println("必填校验拦截: 缺少 id 或 name")
	}

	// 类型不匹配的报错长什么样
	var m5 MemberDTO
	fmt.Println("类型不匹配的报错:", json.Unmarshal([]byte(`{"age":"三十"}`), &m5))

	// ---- 5. map 序列化时键会被排序（与遍历随机不同）----
	mm := map[string]int{"delta": 4, "alpha": 1, "charlie": 3}
	bm, _ := json.Marshal(mm)
	fmt.Println("map 序列化:", string(bm), " ← 键按字典序，不用担心顺序")

	// ---- 6. 时间的坑 ----
	var zero time.Time
	fmt.Printf("零值 time.Time: %v  IsZero=%v  序列化为 %s\n", zero, zero.IsZero(), mustJSON(zero))
	fmt.Printf("带时区的时间: %v  UTC 化: %v  Unix=%d\n", now, now.UTC(), now.Unix())

	// 反序列化非法时间会报错：json 把 time.Time 的解析错误包进了 UnmarshalTypeError
	var bad2 MemberDTO
	errT := json.Unmarshal([]byte(`{"created_at":"不是时间"}`), &bad2)
	fmt.Printf("非法时间字段会报错: %v，错误类型 %T\n", errT != nil, errT)

	// ---- 7. 实际工程模式：解析 + 默认值 + 校验 ----
	type CreateReq struct {
		Name  string `json:"name"`
		Age   int    `json:"age"`
		Email string `json:"email"`
	}
	// 合法请求：注意不能有多余字段，否则严格模式会拒绝
	req, err := decodeStrict(`{"name":"小兰","age":22,"email":"lan@example.com"}`)
	if err != nil {
		fmt.Println("解码失败:", err)
	} else {
		fmt.Printf("解码成功: %+v\n", req)
	}

	// 同一个请求多带一个 referrer 字段，严格模式直接拒绝——这是「客户端加了字段就崩」的代价
	_, err = decodeStrict(`{"name":"小兰","age":22,"referrer":"ads"}`)
	fmt.Println("多余字段的报错:", err)
	_, err = decodeStrict(`{"name":"","age":-1}`)
	fmt.Println("非法业务值的错误:", err)
}

func mustJSON(t time.Time) string {
	b, _ := json.Marshal(t)
	return string(b)
}

func decodeStrict(s string) (CreateReq, error) {
	var r CreateReq
	dec := json.NewDecoder(strings.NewReader(s))
	dec.DisallowUnknownFields()
	if err := dec.Decode(&r); err != nil {
		return r, fmt.Errorf("请求体解析失败: %w", err)
	}
	if r.Name == "" {
		return r, errors.New("name 不能为空")
	}
	if r.Age < 0 || r.Age > 150 {
		return r, errors.New("age 必须在 0..150 之间")
	}
	return r, nil
}

package main

import "fmt"

// ---- 1. 隐式实现：这里没有任何 implements 关键字 ----

// Notifier 是一个由「使用方」定义的最小需求
type Notifier interface {
	Notify(msg string) error
}

// EmailSender 完全没有提到 Notifier，却自动满足它
type EmailSender struct {
	Addr string
	Sent []string
}

func (e *EmailSender) Notify(msg string) error {
	if e.Addr == "" {
		return fmt.Errorf("发件地址为空")
	}
	e.Sent = append(e.Sent, msg)
	return nil
}

// SMSSender 同样不声明，也满足 Notifier
type SMSSender struct {
	Phone string
}

func (s *SMSSender) Notify(msg string) error {
	if len(s.Phone) != 11 {
		return fmt.Errorf("手机号不合法: %s", s.Phone)
	}
	return nil
}

// ---- 2. 编译期断言：不是开关，只是让编译器帮你查 ----
// var _ Notifier = (*EmailSender)(nil)  这行的作用是：如果 EmailSender
// 哪天不再满足 Notifier，这一行会立刻编译报错，而不是等到某个调用点才炸。
var _ Notifier = (*EmailSender)(nil)
var _ Notifier = (*SMSSender)(nil)

// ---- 3. 方法集：值接收者 vs 指针接收者 ----

type Counter struct{ n int }

// 值接收者：Counter 和 *Counter 的方法集里都有 Bump
func (c Counter) Bump() int { c.n++; return c.n }

// 指针接收者：只有 *Counter 的方法集里有 Add
func (c *Counter) Add(delta int) int { c.n += delta; return c.n }

// SmallIface 只要值接收者的方法 → Counter 和 *Counter 都满足
type SmallIface interface{ Bump() int }

// BigIface 要指针接收者的方法 → 只有 *Counter 满足
type BigIface interface {
	Bump() int
	Add(int) int
}

// ---- 4. 空接口 any：传进来到处都合法，取出来要断言 ----

func describe(v any) string {
	switch t := v.(type) {
	case nil:
		return "nil"
	case string:
		return "字符串: " + t
	case int:
		return fmt.Sprintf("整数: %d", t)
	case []int:
		return fmt.Sprintf("整型切片: len=%d", len(t))
	case error:
		return "错误: " + t.Error()
	default:
		return fmt.Sprintf("其他类型 %T", t)
	}
}

// 断言的两种形式：安全版带 ok，panic 版不带
func asInt(v any) (int, bool) {
	i, ok := v.(int)
	return i, ok
}

// ---- 5. 接口嵌套：组合小接口 ----

type Reader interface {
	Read(p []byte) (int, error)
}
type Writer interface {
	Write(p []byte) (int, error)
}
type Closer interface {
	Close() error
}
// ReadWriteCloser 组合了三个小接口
type ReadWriteCloser interface {
	Reader
	Writer
	Closer
}

// Buffer 实现了全部三个方法，自动满足组合接口
type Buffer struct{ data []byte }

func (b *Buffer) Read(p []byte) (int, error)  { return copy(p, b.data), nil }
func (b *Buffer) Write(p []byte) (int, error) { b.data = append(b.data, p...); return len(p), nil }
func (b *Buffer) Close() error                { b.data = nil; return nil }

func main() {
	// ---- 隐式实现：切片里装两个不同的实现 ----
	senders := []Notifier{
		&EmailSender{Addr: "a@homecube.dev"},
		&SMSSender{Phone: "13800000000"},
	}
	for i, s := range senders {
		if err := s.Notify(fmt.Sprintf("第 %d 条通知", i)); err != nil {
			fmt.Printf("发送失败: %v\n", err)
		} else {
			fmt.Printf("发送成功: %T\n", s)
		}
	}
	// 看 EmailSender 真的收到了两条
	es := senders[0].(*EmailSender)
	fmt.Printf("EmailSender 收到: %v\n", es.Sent)

	// ---- nil 陷阱：接口装了 nil 指针，接口本身 != nil ----
	var nilSender *EmailSender
	var n Notifier = nilSender
	fmt.Printf("nil 指针装进接口后 n == nil ? %v  ← 这是 Go 最经典的陷阱\n", n == nil)

	// ---- 方法集 ----
	c := Counter{n: 1}
	var si SmallIface = c // 值类型可以：SmallIface 只要值接收者的方法
	v := si.Bump()
	fmt.Printf("值类型满足 SmallIface，Bump 返回 %d，但 c.n 仍是 %d（值接收者改的是副本）\n", v, c.n)

	var bi BigIface = &c // 值类型不满足 BigIface，必须传指针
	bi.Bump()
	bi.Add(10)
	fmt.Printf("指针类型满足 BigIface，Bump+Add 后: c.n=%d\n", c.n)

	// 下面这行编译不过（注释掉看报错）：
	// var bi2 BigIface = c
	// cannot use c (variable of type Counter) as BigIface value in variable declaration:
	// Counter does not implement BigIface (missing method Add)
	// 原因：Counter 的方法集里只有值接收者的 Bump，指针接收者的 Add 不在内

	// ---- 空接口 ----
	fmt.Println(describe("小林"))
	fmt.Println(describe(42))
	fmt.Println(describe([]int{1, 2, 3}))
	fmt.Println(describe(fmt.Errorf("boom")))
	fmt.Println(describe(3.14))
	fmt.Println(describe(nil))

	// 安全断言 vs panic 断言
	v, ok := asInt("不是整数")
	fmt.Printf("asInt(\"不是整数\") = %d, ok=%v  ← 断言失败返回零值\n", v, ok)
	v2, ok2 := asInt(7)
	fmt.Printf("asInt(7) = %d, ok=%v\n", v2, ok2)

	// 直接断言失败会 panic：
	// x := any("字符串").(int)
	// panic: interface conversion: interface {} is string, not int

	// ---- 接口嵌套 ----
	var rwc ReadWriteCloser = &Buffer{}
	rwc.Write([]byte("hello "))
	rwc.Write([]byte("homecube"))
	buf := make([]byte, 32)
	n2, _ := rwc.Read(buf)
	fmt.Printf("组合接口读回: %q（读 %d 字节）\n", string(buf[:n2]), n2)
	fmt.Printf("Close 的错误: %v\n", rwc.Close())

	// 接口的零成本断言：*Buffer 同时满足 Reader/Writer/Closer
	var _ Reader = (*Buffer)(nil)
	var _ Writer = (*Buffer)(nil)
	var _ Closer = (*Buffer)(nil)
	fmt.Println("Buffer 同时满足 Reader/Writer/Closer")
}

package main

import (
	"errors"
	"fmt"
	"sort"
	"time"
)

// ============ 窄接口：一个方法一个职责 ============

// MemberFinder 只要求「能按 id 查到人」。注意定义在这里（消费方），不在 store 包里。
type MemberFinder interface {
	Find(id string) (Member, error)
}

// MemberSaver 只要求「能存人」
type MemberSaver interface {
	Save(m Member) error
}

// FindSaver 是前面两个的组合：两个方法，谁要两个一起用就声明这个
type FindSaver interface {
	MemberFinder
	MemberSaver
}

// Clock 是 Go 社区最经典的接口：为了让「时间相关」的逻辑可测试
type Clock interface {
	Now() time.Time
}

// ============ 实现一：内存实现（同时也是测试替身）============

type memStore struct {
	items map[string]Member
}

func newMemStore() *memStore {
	return &memStore{items: map[string]Member{}}
}

func (s *memStore) Find(id string) (Member, error) {
	m, ok := s.items[id]
	if !ok {
		return Member{}, fmt.Errorf("成员 %s 不存在", id)
	}
	return m, nil
}

func (s *memStore) Save(m Member) error {
	s.items[m.ID] = m
	return nil
}

// 只读方法：不在任何被要求的接口里，但具体类型上可以调用——这正是「返回具体类型」的价值
func (s *memStore) Count() int { return len(s.items) }

// ============ 实现二：另一个实现，证明接口可以替换 ============

type errStore struct{ code int }

func (e *errStore) Find(id string) (Member, error) {
	return Member{}, errors.New("存储层不可用")
}
func (e *errStore) Save(m Member) error {
	return errors.New("存储层不可用")
}

// ============ 依赖倒置：Service 依赖接口，不依赖实现 ============

// NewMemberService 的参数是接口，调用方可以注入任何实现
func NewMemberService(finder MemberFinder, saver MemberSaver, clk Clock) *MemberService {
	return &MemberService{finder: finder, saver: saver, clock: clk}
}

type MemberService struct {
	finder MemberFinder
	saver  MemberSaver
	clock  Clock
}

func (s *MemberService) Register(name, role string) error {
	if name == "" {
		return errors.New("name 不能为空")
	}
	m := Member{
		ID:       "m_" + name,
		Name:     name,
		Role:     role,
		JoinedAt: s.clock.Now().Format(time.DateOnly), // 依赖 clock 而不是直接 time.Now
	}
	return s.saver.Save(m)
}

func (s *MemberService) Get(id string) (Member, error) {
	return s.finder.Find(id)
}

// 依赖倒置的额外收益：同一份 Service 代码能配不同的实现
func (s *MemberService) Rename(oldID, newName string) error {
	m, err := s.finder.Find(oldID)
	if err != nil {
		return fmt.Errorf("改名失败，先查人: %w", err)
	}
	m.Name = newName
	return s.saver.Save(m)
}

type Member struct {
	ID       string
	Name     string
	Role     string
	JoinedAt string
}

// ============ 测试替身：这是「接口小」的真正回报 ============

// 固定时钟：让「加入日期」在测试里是确定的
type fixedClock struct{ t time.Time }

func (f fixedClock) Now() time.Time { return f.t }

// 假实现：只记录调用，不真的发消息
type recordingNotifier struct {
	sent []string
	err  error
}

func (r *recordingNotifier) Notify(msg string) error {
	if r.err != nil {
		return r.err
	}
	r.sent = append(r.sent, msg)
	return nil
}

func (r *recordingNotifier) Sent() []string {
	cp := make([]string, len(r.sent))
	copy(cp, r.sent)
	return cp
}

// ============ 多接口：一个类型同时满足多个接口 ============

type Sender interface {
	Send(to, body string) error
}

type Auditor interface {
	Audit(action string)
}

// NotifySender 同时有 Send 和 Audit，也满足上面那些小接口
type NotifySender struct {
	notifier Notifier2
	audits   []string
}

type Notifier2 interface{ Notify(string) error }

func (s *NotifySender) Send(to, body string) error {
	return s.notifier.Notify("发给 " + to + ": " + body)
}

func (s *NotifySender) Audit(action string) { s.audits = append(s.audits, action) }

// CanNotify 演示「一个方法满足多个接口」
func CanNotify(v any) bool {
	switch v.(type) {
	case interface{ Notify(string) error }:
		return true
	case interface{ Send(string, string) error }:
		return true
	}
	return false
}

func main() {
	clk := fixedClock{t: time.Date(2026, 10, 15, 10, 0, 0, 0, time.UTC)}

	// ---- 1. 依赖注入：同一份 Service 配不同实现 ----
	store := newMemStore()
	svc := NewMemberService(store, store, clk)

	if err := svc.Register("小林", "owner"); err != nil {
		fmt.Println("注册失败:", err)
	}
	if err := svc.Register("小森", "member"); err != nil {
		fmt.Println("注册失败:", err)
	}
	fmt.Printf("存储里有 %d 人（Count 是 memStore 特有方法，接口上没声明）\n", store.Count())

	m, err := svc.Get("m_小林")
	fmt.Printf("查到: %+v err=%v\n", m, err)

	// 查不到：服务层包装了错误
	_, err = svc.Get("不存在")
	fmt.Printf("查不到时: %v\n", err)
	fmt.Printf("原始错误仍在链上: %v\n", errors.Unwrap(err))

	if err := svc.Rename("m_小林", "小林改名"); err != nil {
		fmt.Println("改名失败:", err)
	}
	m2, _ := svc.Get("m_小林")
	fmt.Printf("改名后: %s\n", m2.Name)

	// ---- 2. 换一个坏实现，Service 代码一行不改 ----
	badSvc := NewMemberService(&errStore{code: 500}, &errStore{code: 500}, clk)
	fmt.Println("坏存储下注册:", badSvc.Register("小兰", "member"))
	fmt.Println("坏存储下查询:", badSvc.Get("m_小兰"))

	// ---- 3. 嵌入组合：FindSaver 同时要求两个方法 ----
	var fs FindSaver = newMemStore()
	_ = fs.Save(Member{ID: "m_组合", Name: "组合", Role: "member"})
	got, _ := fs.Find("m_组合")
	fmt.Printf("组合接口可用: %s\n", got.Name)

	// 只声明 Finder 的话，实现可以只有 Find 一个方法
	onlyFind := &onlyFinder{}
	var f1 MemberFinder = onlyFind
	fmt.Printf("单方法接口也能满足: %s\n", f1.Find("x").Name)

	// ---- 4. 多接口：一个值满足几个小接口 ----
	rec := &recordingNotifier{}
	ns := &NotifySender{notifier: rec}
	var send Sender = ns
	var aud Auditor = ns
	send.Send("小林", "晚安")
	aud.Audit("发送晚安")
	fmt.Printf("发送记录: %v\n", rec.Sent())
	fmt.Printf("审计记录: %v\n", ns.audits)

	// CanNotify 用内联接口做「结构化类型」判断
	fmt.Printf("rec 满足 Notify 形状? %v\n", CanNotify(rec))
	fmt.Printf("ns 满足 Notify 形状? %v\n", CanNotify(ns))
	fmt.Printf("42 满足 Notify 形状? %v\n", CanNotify(42))

	// ---- 5. 错误也能被接口化：一个方法也能满足 error ----
	// （上面 errStore 里的 errors.New 就演示了：error 本身就是只有一个 Error() 的接口）

	// ---- 6. 方法集的实际影响 ----
	type hasCount interface{ Count() int }
	var hc hasCount = store
	fmt.Printf("*memStore 满足 Count 接口: %d\n", hc.Count())

	// 值类型不满足（因为 Count 是指针接收者，注释掉看报错）：
	// var hc2 hasCount = *store
	// cannot use *store (value of type memStore) as hasCount: memStore does not implement
	// hasCount (missing method Count) —— 因为 Count 是指针接收者，值类型的方法集里没有它

	// ---- 7. 演示 fake 实现：不需要任何测试框架 ----
	notify := func(n Notifier2, msg string) { _ = n.Notify(msg) }
	fake := &recordingNotifier{err: errors.New("通道故障")}
	notify(fake, "这条不会被记录")
	fmt.Printf("替身记录了 %d 条，错误=%v\n", len(fake.Sent()), fake.err)

	// 排序输出让断言稳定
	rec2 := &recordingNotifier{}
	notify(rec2, "A")
	notify(rec2, "B")
	sort.Strings(rec2.sent)
	fmt.Printf("稳定断言用: %v\n", rec2.Sent())
}

// onlyFinder 只实现了 Find，故意不实现 Save——用来演示「接口小才容易实现」
type onlyFinder struct{}

func (o *onlyFinder) Find(id string) (Member, error) {
	return Member{ID: id, Name: "只有 Find"}, nil
}

package main

import (
	"errors"
	"fmt"
	"strings"
)

// ============ 1. 哨兵错误：包级导出变量，供调用方用 errors.Is 判断 ============

var (
	ErrNotFound  = errors.New("成员不存在")
	ErrForbidden = errors.New("权限不足")
)

// errors.New 在热路径里每次调用都会新分配，所以只用它创建包级哨兵
func newBadError(id string) error {
	return errors.New("成员 " + id + " 不存在") // 演示反模式：每次都分配，且无法被 errors.Is 识别
}

// ============ 2. fmt.Errorf + %w：包装并保留原始错误 ============

// load 从「数据源」取人，底层失败原样透出
func load(id string) (Member, error) {
	if id == "" {
		return Member{}, ErrNotFound // 哨兵错误直接返回，不包装（没有额外信息可加）
	}
	if strings.HasPrefix(id, "sys_") {
		return Member{}, ErrForbidden
	}
	return Member{ID: id, Name: "小林", Role: "owner"}, nil
}

// service 层：包装并补充「我在哪一步失败」
func service(id string) (Member, error) {
	m, err := load(id)
	if err != nil {
		return Member{}, fmt.Errorf("load 成员 %q 失败: %w", id, err)
	}
	if m.Role != "owner" {
		return Member{}, fmt.Errorf("成员 %q 角色是 %s，不是 owner: %w", id, m.Role, ErrForbidden)
	}
	return m, nil
}

// handler 层：再包装一层，链路变长
func handler(id string) (string, error) {
	m, err := service(id)
	if err != nil {
		return "", fmt.Errorf("处理请求 GET /members/%s 失败: %w", id, err)
	}
	return m.Name, nil
}

// ============ 3. %v 会断链：反例演示 ============

func serviceBroken(id string) (Member, error) {
	m, err := load(id)
	if err != nil {
		return Member{}, fmt.Errorf("load 成员 %q 失败: %v", id, err) // ← 错：用 %v
	}
	return m, nil
}

// ============ 4. 一层包装多个错误（Go 1.20+）============

func validate(id string, age int) error {
	var errs []error
	if id == "" {
		errs = append(errs, ErrNotFound)
	}
	if age < 0 {
		errs = append(errs, fmt.Errorf("年龄 %d 不合法", age))
	}
	if len(errs) == 0 {
		return nil
	}
	if len(errs) == 1 {
		return errs[0]
	}
	return fmt.Errorf("%d 项校验失败: %w", len(errs), errors.Join(errs...))
}

// ============ 5. 错误消息的措辞规范 ============

// 惯例：小写开头、不以标点结尾、描述「发生了什么」
var ErrBadInput = errors.New("参数不合法")

func makeUserMessage(err error) string {
	return "无法完成操作: " + err.Error()
}

// ============ 6. nil error 的陷阱：接口装箱 ============

type Sender struct{ err error }

func (s *Sender) Fail() error {
	var e *Sender = nil
	return e // ← 危险：这个 error 装了一个 nil 的 *Sender，接口本身不是 nil
}

// ============ 7. panic 的正当用途：初始化失败 ============

func mustLoadConfig(path string) string {
	if path == "" {
		// 启动期配置缺失：没有「谁来处理」的调用栈，panic 是合理的
		panic("配置路径为空，无法启动")
	}
	return "loaded:" + path
}

func main() {
	// ---- 1. 错误消息逐层累积 ----
	name, err := handler("m_001")
	fmt.Printf("成功: name=%s err=%v\n", name, err)

	_, err = handler("sys_x")
	fmt.Printf("失败: %v\n", err)
	fmt.Printf("  类型: %T\n", err)

	// ---- 2. errors.Is 顺着 %w 链找到最底层的哨兵 ----
	fmt.Printf("errors.Is(err, ErrForbidden) = %v\n", errors.Is(err, ErrForbidden))
	fmt.Printf("errors.Is(err, ErrNotFound) = %v\n", errors.Is(err, ErrNotFound))

	// ---- 3. errors.Unwrap 一层一层拆 ----
	h := err
	depth := 0
	for h != nil {
		depth++
		fmt.Printf("  第 %d 层: %v\n", depth, h)
		h = errors.Unwrap(h)
	}
	fmt.Printf("错误链共 %d 层\n", depth)

	// ---- 4. %v 断链的后果 ----
	_, errBroken := serviceBroken("sys_x")
	fmt.Printf("用 %%v 包装后: %v\n", errBroken)
	fmt.Printf("  errors.Is 能找到哨兵吗? %v  ← 链断了，找不到\n", errors.Is(errBroken, ErrForbidden))
	fmt.Printf("  只能靠字符串匹配，极不可靠: %v\n", strings.Contains(errBroken.Error(), "权限不足"))

	// ---- 5. 多错误 Join ----
	e1 := validate("", -1)
	fmt.Printf("多项校验失败: %v\n", e1)
	fmt.Printf("  errors.Is(err, ErrNotFound) = %v\n", errors.Is(e1, ErrNotFound))
	fmt.Printf("  errors.Is(err, ErrForbidden) = %v\n", errors.Is(e1, ErrForbidden))
	fmt.Printf("只填 age: %v\n", validate("m_1", -1))

	// ---- 6. 哨兵错误 vs errors.New 每次分配 ----
	bad := newBadError("m_9")
	fmt.Printf("动态 errors.New: %v，errors.Is 找不到任何哨兵: %v\n", bad, errors.Is(bad, ErrNotFound))

	// ---- 7. 错误消息的措辞 ----
	fmt.Println(makeUserMessage(fmt.Errorf("%w: name 不能为空", ErrBadInput)))

	// ---- 8. nil error 陷阱 ----
	s := &Sender{}
	gotErr := s.Fail()
	fmt.Printf("返回 nil 指针装进 error 后 err == nil ? %v  ← 陷阱\n", gotErr == nil)

	// ---- 9. 错误类型信息比字符串有用（明天 errors.As 展开）----
	fmt.Printf("用 %%T 能看到具体类型: %T\n", err)
	fmt.Printf("只用字符串你什么都不知道，只能靠 == 比字符串（不可靠）\n")

	// ---- 10. panic 的正当用途 ----
	defer func() {
		if r := recover(); r != nil {
			fmt.Printf("recover 捕获到 panic: %v\n", r)
		}
	}()
	fmt.Printf("mustLoadConfig(\"cfg.yaml\") = %s\n", mustLoadConfig("cfg.yaml"))
	mustLoadConfig("") // 触发 panic，被上面的 defer 接住

	// defer 里的 recover 只能救「同一个 goroutine」的 panic
	fmt.Println("（如果 panic 发生在别的 goroutine 里，这里的 recover 救不了，整个程序会挂）")
}

package main

import (
	"errors"
	"fmt"
	"net/http"
	"strings"
)

// ============ 1. 哨兵错误（用于 errors.Is）============

var (
	ErrNotFound  = errors.New("成员不存在")
	ErrForbidden = errors.New("权限不足")
	ErrInvalid   = errors.New("参数不合法")
	ErrConflict  = errors.New("数据冲突")
)

// ============ 2. 自定义错误类型（用于 errors.As 取字段）============

// ValidationError 携带「哪个字段、为什么不合法」
type ValidationError struct {
	Field  string
	Reason string
	Err    error // 包装的底层错误，可为 nil
}

func (e *ValidationError) Error() string {
	if e.Err != nil {
		return fmt.Sprintf("字段 %s 不合法: %s（原因: %v）", e.Field, e.Reason, e.Err)
	}
	return fmt.Sprintf("字段 %s 不合法: %s", e.Field, e.Reason)
}

// Unwrap 让 errors.Is/As 能继续挖到包装的底层错误
func (e *ValidationError) Unwrap() error { return e.Err }

// Is 方法让「任何 ValidationError」都算同一类：errors.Is(err, &ValidationError{})
func (e *ValidationError) Is(target error) bool {
	_, ok := target.(*ValidationError)
	return ok
}

type Member struct {
	ID   string
	Name string
	Age  int
}

// validateAge 校验年龄，失败时返回带结构的错误
func validateAge(m Member) error {
	switch {
	case m.Age < 0:
		return &ValidationError{Field: "age", Reason: "不能为负数", Err: fmt.Errorf("got %d", m.Age)}
	case m.Age > 150:
		return &ValidationError{Field: "age", Reason: "不能超过 150", Err: fmt.Errorf("got %d", m.Age)}
	}
	return nil
}

func validateName(m Member) error {
	if strings.TrimSpace(m.Name) == "" {
		return &ValidationError{Field: "name", Reason: "不能为空"}
	}
	return nil
}

// service 收集所有校验错误并包装成哨兵 + 结构化细节
func service(m Member) error {
	if m.ID == "" {
		return ErrNotFound
	}
	if err := validateName(m); err != nil {
		return fmt.Errorf("校验 name: %w", err) // 包装：链上有 ValidationError
	}
	if err := validateAge(m); err != nil {
		return fmt.Errorf("校验 age: %w", err)
	}
	return nil
}

// ============ 3. 包装多次：链上有多层 ============

func handler(id string, m Member) (int, error) {
	if err := service(m); err != nil {
		return 0, fmt.Errorf("handler 注册成员 %s: %w", id, err)
	}
	return http.StatusCreated, nil
}

// ============ 4. 「同类即匹配」：用 Is 方法按类型判 ============

// ClassifiedError 展示「只看类型不看具体值」的匹配
type ClassifiedError struct {
	Code int
	Msg  string
}

func (e *ClassifiedError) Error() string { return fmt.Sprintf("[%d] %s", e.Code, e.Msg) }

func (e *ClassifiedError) Is(target error) bool {
	t, ok := target.(*ClassifiedError)
	if !ok {
		return false
	}
	return t.Code == e.Code // Code 相同就算同一类
}

func main() {
	// ---- 1. == 在包装后失效 ----
	err := service(Member{ID: "m_1"})
	fmt.Printf("err == ErrNotFound ? %v\n", err == ErrNotFound)

	_, errWrapped := handler("m_1", Member{ID: "m_1"})
	fmt.Printf("包装后 err == ErrNotFound ? %v  ← == 失效了\n", errWrapped == ErrNotFound)
	fmt.Printf("但 errors.Is 穿透所有层: %v  ← 正确\n", errors.Is(errWrapped, ErrNotFound))
	fmt.Printf("链上消息: %v\n", errWrapped)

	// ---- 2. errors.As 取出结构化字段 ----
	_, errAge := handler("m_2", Member{ID: "m_2", Age: 200})
	var ve *ValidationError
	if errors.As(errAge, &ve) {
		fmt.Printf("errors.As 取出: Field=%q Reason=%q\n", ve.Field, ve.Reason)
		fmt.Printf("Unwrap 到底层: %v\n", ve.Unwrap())
		fmt.Printf("Unwrap 出的错误在链上吗? %v\n", errors.Is(errAge, ve.Unwrap()))
	} else {
		fmt.Println("不是 ValidationError")
	}

	// name 字段的错误（不同的 Field）
	_, errName := handler("m_3", Member{ID: "m_3", Name: "  "})
	var ve2 *ValidationError
	errors.As(errName, &ve2)
	fmt.Printf("另一条链: Field=%q Reason=%q\n", ve2.Field, ve2.Reason)

	// ---- 3. errors.As 的双指针用法：写成 ve 会编译失败 ----
	// var ve3 *ValidationError
	// errors.As(errAge, ve3)  ← 编译错误：needs *(*ValidationError), not *ValidationError
	// 正确：errors.As(errAge, &ve3)  —— 注意是 &ve3（指针的指针）

	// ---- 4. Is 方法实现「同类即匹配」----
	ce1 := &ClassifiedError{Code: 1001, Msg: "参数错误"}
	ce2 := &ClassifiedError{Code: 1001, Msg: "另一个 1001"}
	ce3 := &ClassifiedError{Code: 3001, Msg: "权限错误"}
	fmt.Printf("ce1.Is(1001 的空壳) = %v\n", errors.Is(ce1, &ClassifiedError{Code: 1001}))
	fmt.Printf("ce1.Is(3001 的空壳) = %v\n", errors.Is(ce1, &ClassifiedError{Code: 3001}))
	fmt.Printf("ce1 == ce2 ? %v（不同对象，== 失败）\n", ce1 == ce2)
	fmt.Printf("但 errors.Is(ce1, ce2) = %v ← Is 方法让它们「同类」\n", errors.Is(ce1, ce2))

	// ---- 5. 完整形态：Is 判类别 → As 取细节 → 兜底 500 ----
	status, body := handleCreate(Member{ID: "m_4", Name: "小林", Age: 30})
	fmt.Printf("正常: status=%d body=%s\n", status, body)

	status, body = handleCreate(Member{ID: "m_5", Name: "小森", Age: 200})
	fmt.Printf("字段错误: status=%d body=%s  ← Is 定类别，As 取字段填响应体\n", status, body)

	status, body = handleCreate(Member{Name: "小兰", Age: 22})
	fmt.Printf("不存在: status=%d body=%s\n", status, body)

	status, body = handleCreate(Member{ID: "m_6", Name: "小谷", Age: 22})
	fmt.Printf("未知错误兜底: status=%d body=%s  ← 不泄露内部信息\n", status, body)

	// ---- 6. errors.Is(nil, nil) 为 true，但直接判 nil 更快 ----
	fmt.Printf("errors.Is(nil, nil) = %v\n", errors.Is(nil, nil))

	// ---- 7. 多层里取「最内层」的字段（手动逐层 Unwrap）----
	fmt.Println("逐层展开，找到最内层的 ValidationError:")
	for cur := errAge; cur != nil; cur = errors.Unwrap(cur) {
		var v *ValidationError
		if errors.As(cur, &v) {
			fmt.Printf("  在这一层找到: Field=%s\n", v.Field)
		}
	}
}

// handleCreate 演示「Is 判类别 + As 取细节 + 兜底」的完整形态
func handleCreate(m Member) (int, string) {
	err := service(m)
	if err == nil {
		return http.StatusCreated, `{"ok":true}`
	}
	// 第一步：errors.Is 判类别 → 决定状态码
	switch {
	case errors.Is(err, ErrNotFound):
		return http.StatusNotFound, `{"error":"not_found"}`
	case errors.Is(err, ErrInvalid):
		// 第二步：errors.As 取结构化字段 → 填响应体
		var ve *ValidationError
		if errors.As(err, &ve) {
			return http.StatusUnprocessableEntity, fmt.Sprintf(`{"error":"invalid","field":%q,"reason":%q}`, ve.Field, ve.Reason)
		}
		return http.StatusUnprocessableEntity, `{"error":"invalid"}`
	case errors.Is(err, ErrForbidden):
		return http.StatusForbidden, `{"error":"forbidden"}`
	}
	// 第三步：兜底。不认识的错误 → 500，且不把内部消息暴露给客户端
	_ = err // 真实代码里这里应该 log.Printf("internal error: %v", err)
	return http.StatusInternalServerError, `{"error":"internal"}`
}

package main

import (
	"errors"
	"fmt"
	"os"
	"sort"
	"strings"
	"time"
)

// ============ 1. 标准形状：(value, error) ============

func divide(a, b float64) (float64, error) {
	if b == 0 {
		return 0, fmt.Errorf("除数不能为 0（a=%v）", a)
	}
	return a / b, nil
}

// ============ 2. (value, bool)：没找到是正常结果，不是错误 ============

func lookupMember(id string, db map[string]string) (string, bool) {
	v, ok := db[id]
	return v, ok
}

// 注意返回 bool 的函数名用 Lookup / Contains 这类「本来就期待可能没有」的词

// ============ 3. 多返回值：什么时候该收进结构体 ============

// 不好：三个裸值，调用方容易搞错顺序
func statsTriple(xs []int) (int, int, error) {
	if len(xs) == 0 {
		return 0, 0, errors.New("空切片")
	}
	mn, mx := xs[0], xs[0]
	for _, x := range xs {
		if x < mn {
			mn = x
		}
		if x > mx {
			mx = x
		}
	}
	return mn, mx, nil
}

// 好：命名字段，调用方自解释
type Stat struct {
	Min int
	Max int
	Sum int
}

func stats(xs []int) (Stat, error) {
	if len(xs) == 0 {
		return Stat{}, errors.New("空切片")
	}
	st := Stat{Min: xs[0], Max: xs[0]}
	for _, x := range xs {
		if x < st.Min {
			st.Min = x
		}
		if x > st.Max {
			st.Max = x
		}
		st.Sum += x
	}
	return st, nil
}

// ============ 4. 命名返回值 + defer：把 panic 转成 error ============

// SafeDiv 的命名返回值 err 是给 defer 用的：recover 之后写 err = ...，
// 这个赋值就是函数的实际返回值。这就是所有「绝不 panic 出边界」的库函数的写法。
//
// 注意这里用**整数**除法：整数除以 0 是 runtime error（panic），
// 而浮点除以 0 只返回 +Inf / NaN，不会 panic——这个差别很容易记反。
func SafeDiv(a, b int) (result int, err error) {
	defer func() {
		if r := recover(); r != nil {
			err = fmt.Errorf("SafeDiv 内部 panic: %v", r)
			result = 0
		}
	}()
	return a / b, nil // ← b=0 会 panic（整数除零），被 defer 接住
}

// ============ 5. defer 修改普通命名返回值（计时器）============

// elapsed 是 defer 改命名返回值最经典的用法：
// 先在函数体开头取开始时间，用 defer 在「函数即将返回时」算出耗时并写进 ms。
// 注意 return 0 只是占位——真正的返回值由那个 defer 决定。
func elapsed(do func()) (ms int64) {
	start := time.Now()
	defer func() {
		ms = time.Since(start).Milliseconds()
	}()
	do()
	return 0 // 占位，会被上面的 defer 覆盖
}

// 要让 elapsed 可测（呼应 d14），把 time.Now 换成 d14 里的 Clock 接口即可：
// 此时测试可以传一个固定时钟，让 ms 恒定。这里保持简单，直接用 time 包。
var _ = time.Since

// ============ 6. 多错误收集：什么时候该聚合返回 ============

// Validate 收集所有字段错误而不是遇到第一个就返回——表单场景需要
type FieldErrors map[string][]string

func (fe FieldErrors) Error() string {
	keys := make([]string, 0, len(fe))
	for k := range fe {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	parts := make([]string, 0, len(keys))
	for _, k := range keys {
		parts = append(parts, fmt.Sprintf("%s: %v", k, fe[k]))
	}
	return "字段校验失败: " + strings.Join(parts, "; ")
}

func ValidateMember(name string, age int, email string) error {
	var fe FieldErrors
	if strings.TrimSpace(name) == "" {
		fe["name"] = append(fe["name"], "不能为空")
	}
	if age < 0 {
		fe["age"] = append(fe["age"], "不能为负数")
	}
	if !strings.Contains(email, "@") {
		fe["email"] = append(fe["email"], "格式不正确")
	}
	if len(fe) == 0 {
		return nil
	}
	return fe
}

// ============ 7. 何时 panic：程序启动期的不可恢复失败 ============

type Config struct {
	DSN string
}

func mustLoadConfig(path string) Config {
	// 启动期：没有「谁来处理」的调用栈，panic 是简洁的做法
	if path == "" {
		panic("配置路径为空")
	}
	if path == "missing.yaml" {
		panic("配置文件不存在: " + path)
	}
	return Config{DSN: "postgres://localhost/homecube"}
}

// ============ 8. _ 忽略返回值：什么时候可以 ============

func init() {
	// 标准库大量使用 _ 忽略错误（写日志、关文件这类失败影响不大的场景）
	_ = os.Setenv("HOME", "/tmp")
}

func main() {
	// ---- 1. 标准形状 ----
	v, err := divide(10, 4)
	fmt.Printf("divide 成功: v=%.2f err=%v\n", v, err)
	v, err = divide(1, 0)
	fmt.Printf("divide 失败: v=%.2f err=%v  ← 失败时 v 是零值，不要用\n", v, err)

	// ---- 2. (value, bool) ----
	db := map[string]string{"m_1": "小林"}
	if name, ok := lookupMember("m_1", db); ok {
		fmt.Printf("查到: %s\n", name)
	}
	if _, ok := lookupMember("m_999", db); !ok {
		fmt.Println("没查到：用 bool 而不是 error，因为「不存在」是正常结果")
	}

	// ---- 3. 多个返回值 vs 结构体 ----
	xs := []int{3, 1, 4, 1, 5}
	mn, mx, err := statsTriple(xs)
	fmt.Printf("三元组: min=%d max=%d err=%v  ← 要记住顺序\n", mn, mx, err)

	st, err := stats(xs)
	fmt.Printf("结构体: %+v err=%v  ← 自解释\n", st, err)

	// ---- 4. 命名返回值 + defer + recover ----
	fmt.Println("正常:", SafeDiv(10, 2))
	r, err := SafeDiv(1, 0)
	fmt.Printf("1/0: result=%d err=%v  ← panic 被 defer 转成 error 了\n", r, err)

	// ---- 5. defer 改写返回值 ----
	fmt.Printf("elapsed 返回值 >= 0 ? %v（毫秒数每次不同，不做断言）\n", elapsed(func() {
		for i := 0; i < 100000; i++ {
			_ = i * i
		}
	}) >= 0)

	// ---- 6. 聚合多个校验错误 ----
	err = ValidateMember("", -1, "bad-email")
	fmt.Printf("聚合错误: %v\n", err)
	var fe FieldErrors
	if errors.As(err, &fe) {
		keys := make([]string, 0, len(fe))
		for k := range fe {
			keys = append(keys, k)
		}
		sort.Strings(keys)
		fmt.Printf("字段 %v 各自 %d 条错误\n", keys, len(fe))
	}

	err = ValidateMember("小林", 30, "lin@example.com")
	fmt.Printf("全部合法时 err=%v  ← nil 表示通过\n", err)

	// ---- 7. panic 的正当场景：启动期 ----
	cfg := mustLoadConfig("config.yaml")
	fmt.Printf("配置加载: %s\n", cfg.DSN)

	defer func() {
		if r := recover(); r != nil {
			fmt.Printf("启动期 panic 被接住: %v\n", r)
		}
	}()
	mustLoadConfig("missing.yaml")

	// ---- 8. 裸 return 只在短函数里出现 ----
	fmt.Println("elapsed 函数里就用了裸 return（return 0），因为 defer 会改写 ms")
}

package main

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

// ============ 1. defer 的 LIFO 与参数求值 ============

func deferOrder() {
	defer fmt.Println("  1. 先注册的 defer（最先执行）")
	defer fmt.Println("  2. 后注册的 defer")
	defer fmt.Println("  3. 最后注册的 defer（最先执行）")
	fmt.Println("  函数体先执行完")
}

// deferArgs 对比「参数注册时求值」与「闭包执行时读取」
func deferArgs() {
	x := 1
	defer fmt.Println("  A. 参数在注册时求值 → x =", x)          // 1
	defer fmt.Println("  B. 参数在注册时求值 → x =", x)          // 1
	defer func() { fmt.Println("  C. 闭包在执行时读 → x =", x) }() // 100
	defer func(v int) { fmt.Println("  D. 值当参数传入 → v =", v) }(x) // 1
	x = 100
}

// 循环里 defer：对比两种写法
func deferInLoopCaptured() {
	for i := 1; i <= 3; i++ {
		defer func() { fmt.Println("  闭包形式 i =", i) }() // 捕获变量
	}
}

func deferInLoopByValue() {
	for i := 1; i <= 3; i++ {
		defer func(n int) { fmt.Println("  参数形式 n =", n) }(i) // 复制值
	}
}

// ============ 2. defer 修改命名返回值 ============

func withDeferredReturn() (n int) {
	defer func() { n = 42 }() // 覆盖
	return 7                    // 先赋给 n=7，再被 defer 改成 42
}

// ============ 3. 循环里 defer 的坑 ============

// ❌ 错误：所有文件同时保持打开
func processFilesWrong(files []string) (opened int, err error) {
	for _, f := range files {
		fh, oerr := os.Open(f)
		if oerr != nil {
			return opened, oerr
		}
		defer fh.Close() // ← 要等函数返回才执行
		opened++
	}
	return opened, nil
}

// ✅ 正确：循环体抽成函数，defer 落在小函数出口
func processOne(f string) error {
	fh, err := os.Open(f)
	if err != nil {
		return fmt.Errorf("打开 %s: %w", f, err)
	}
	defer fh.Close() // ← 在 processOne 返回时立即执行
	buf := make([]byte, 1)
	_, _ = fh.Read(buf)
	return nil
}

func processFilesRight(files []string) error {
	for _, f := range files {
		if err := processOne(f); err != nil {
			return err
		}
	}
	return nil
}

// ============ 4. panic / recover 的正确用法 ============

// recover 必须「直接」写在 defer 的函数体里
func safeCall(name string, fn func()) (err error) {
	defer func() {
		if r := recover(); r != nil {
			err = fmt.Errorf("%s panic 了: %v", name, r)
		}
	}()
	fn()
	return nil
}

// ❌ 无效：recover 放在一个被普通调用的辅助函数里，抓不到 panic
func helperDoingRecover() interface{} {
	return recover() // 不在 defer 上下文里，返回 nil
}

func tryRecoverIndirect(fn func()) (got interface{}) {
	defer func() {
		got = helperDoingRecover() // recover 实际发生在这里，不是 defer 体内
	}()
	fn()
	return nil
}

// 正确：每层自己的 defer 都能 recover（内层先接住）
func nestedRecover(fn func()) (outer string, inner string) {
	defer func() {
		if r := recover(); r != nil {
			outer = fmt.Sprintf("外层也看到了: %v", r)
		}
	}()
	func() {
		defer func() {
			if r := recover(); r != nil {
				inner = fmt.Sprintf("内层接住了: %v", r)
			}
		}()
		fn()
	}()
	return
}

// ============ 5. 库函数把 panic 转 error ============

func SafeParse(s string) (result int, err error) {
	defer func() {
		if r := recover(); r != nil {
			err = fmt.Errorf("SafeParse 内部 panic: %v", r)
			result = 0
		}
	}()
	var p *os.File
	_ = p.Close() // 对 nil 的 *os.File 调 Close 会 panic
	return len(s), nil
}

// ============ 6. 启动期 panic + assert ============

type Config struct{ DSN string }

func MustLoadConfig(path string) Config {
	if path == "" {
		panic("配置路径为空")
	}
	data, err := os.ReadFile(path)
	if err != nil {
		panic(fmt.Sprintf("读配置 %s 失败", filepath.Base(path)))
	}
	parts := strings.SplitN(strings.TrimSpace(string(data)), "=", 2)
	if len(parts) != 2 {
		panic(fmt.Sprintf("配置格式错误，应为 key=value: %q", string(data)))
	}
	return Config{DSN: parts[1]}
}

func assert(cond bool, msg string) {
	if !cond {
		panic("断言失败: " + msg)
	}
}

// ============ 7. 多资源清理：defer 的正确用法 ============

func copyFile(src, dst string) (err error) {
	in, oerr := os.Open(src)
	if oerr != nil {
		return fmt.Errorf("打开源文件: %w", oerr)
	}
	defer in.Close()

	out, cerr := os.Create(dst)
	if cerr != nil {
		return fmt.Errorf("创建目标文件: %w", cerr)
	}
	// 清理失败也要能被调用方知道：命名返回值 err + defer 里补写
	defer func() {
		if cerr := out.Close(); cerr != nil && err == nil {
			err = fmt.Errorf("关闭目标文件: %w", cerr)
		}
	}()

	if _, err = out.ReadFrom(in); err != nil {
		return fmt.Errorf("拷贝内容: %w", err)
	}
	return nil
}

