	fmt.Println("  注意：go func() { panic(...) }() 如果不在 goroutine 内部 recover，")
	fmt.Println("        会导致整个程序崩溃，外层的 recover 拦不住。正确做法是每个 goroutine 自己兜：")
	done := make(chan string, 1)
	go func() {
		defer func() {
			if r := recover(); r != nil {
				done <- fmt.Sprintf("  goroutine 内部自己 recover: %v", r)
			}
		}()
		panic("goroutine 里的 panic")
	}()
	fmt.Println(<-done)
}

package main

import (
	"fmt"
	"sync"
	"time"
)

// ============ 1. go 语句：启动即返回 ============

func work(id int) {
	fmt.Printf("  worker %d 开始（时间未知，取决于调度）\n", id)
	_ = id
}

// ============ 2. 主协程结束 = 全部被杀 ============

// neverFinishes 演示：如果不等它，主协程一走它就没了
func neverFinishes() {
	fmt.Println("  [将要被杀掉的任务] 马上打印这一行，然后试图等 1 秒")
	time.Sleep(time.Second)
	fmt.Println("  [永远打不出来] 因为主协程早退出了")
}

// ============ 3. 正确等待：WaitGroup ============

// 无返回值的任务用 WaitGroup（Add 在前、Done 在 defer、Wait 在主协程）
func runAllWithWaitGroup(n int) {
	var wg sync.WaitGroup
	results := make([]string, 0, n)
	var mu sync.Mutex // 保护 results 的并发写
	for i := 1; i <= n; i++ {
		wg.Add(1) // Add 必须在 go 语句之前
		go func(id int) {
			defer wg.Done()
			mu.Lock()
			results = append(results, fmt.Sprintf("任务%d", id))
			mu.Unlock()
		}(i)
	}
	wg.Wait() // 等所有 Done
	// 输出顺序不保证，所以排序后再打印
	sortStrings(results)
	fmt.Printf("  WaitGroup：%d 个任务全部完成 → %v\n", n, results)
}

func sortStrings(s []string) {
	for i := 1; i < len(s); i++ {
		for j := i; j > 0 && s[j] < s[j-1]; j-- {
			s[j], s[j-1] = s[j-1], s[j]
		}
	}
}

// ============ 4. sleep 是「猜」，不是「等」 ============

func runAllWithSleep(n int) {
	done := make(chan struct{}, n)
	for i := 1; i <= n; i++ {
		go func(id int) {
			time.Sleep(time.Duration(id) * time.Millisecond)
			done <- struct{}{}
		}(i)
	}
	// ❌ 错误：time.Sleep(time.Second) 然后假设都做完了
	time.Sleep(50 * time.Millisecond)
	// ✅ 正确：数 channel 里的信号
	for i := 0; i < n; i++ {
		<-done
	}
	fmt.Println("  用 channel 计数等待：确定等到全部完成")
}

// ============ 5. 数据竞争：不加锁的共享计数 ============

type Counter struct {
	n int
}

func (c *Counter) Inc() { c.n++ }

// 带锁版本
type SafeCounter struct {
	mu sync.Mutex
	n  int
}

func (c *SafeCounter) Inc() {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.n++
}

// ============ 6. goroutine 的代价：起 20000 个不慌 ============

func spawnMany(n int) {
	var wg sync.WaitGroup
	for i := 0; i < n; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			_ = i // 每个 goroutine 只是算一下，立即结束
		}()
	}
	wg.Wait()
	fmt.Printf("  成功启动并等待 %d 个 goroutine\n", n)
}

// ============ 7. 每个 goroutine 自己 recover ============

func safeGo(name string, fn func()) {
	go func() {
		defer func() {
			if r := recover(); r != nil {
				fmt.Printf("  [%s] 内部 recover: %v\n", name, r)
			}
		}()
		fn()
	}()
}

func main() {
	// ---- 1. go 启动即返回 ----
	fmt.Println("=== 1. go 启动即返回 ===")
	// 注意：下面这组是**裸的** go（没有等待），输出顺序不确定；
	// 实际项目里必须有 WaitGroup 或 channel 等它，所以紧接着演示正确写法。
	var wg sync.WaitGroup
	for i := 1; i <= 3; i++ {
		wg.Add(1) // Add 必须在 go 之前
		go func(id int) {
			defer wg.Done()
			work(id)
		}(i)
	}
	wg.Wait()

	// ---- 2. 主协程结束 = 全被杀掉 ----
	fmt.Println("\n=== 2. 主协程结束 = 全部被杀 ===")
	go neverFinishes()
	// 主协程继续执行，下面的打印会发生；
	// 但如果这里 return，第二行就永远打不出来（goroutine 被直接杀死，defer 也不跑）
	time.Sleep(50 * time.Millisecond)
	fmt.Println("  主协程继续活着，所以那个 goroutine 有机会打印第二行")

	// ---- 3. 用 WaitGroup 等一组 ----
	fmt.Println("\n=== 3. 正确的等待：WaitGroup ===")
	runAllWithWaitGroup(4)

	// ---- 4. sleep 是猜，channel 是等 ----
	fmt.Println("\n=== 4. sleep 不是等待机制 ===")
	runAllWithSleep(3)

	// ---- 5. 数据竞争 ----
	fmt.Println("\n=== 5. 共享内存：数据竞争 ===")
	unsafe := &Counter{}
	safe := &SafeCounter{}
	const N = 10000
	var wg2 sync.WaitGroup
	for i := 0; i < N; i++ {
		wg2.Add(2)
		go func() { defer wg2.Done(); unsafe.Inc() }()
		go func() { defer wg2.Done(); safe.Inc() }()
	}
	wg2.Wait()
	fmt.Printf("  %d 次自增：不加锁得到 %d（大概率小于 %d，发生了丢失更新）\n", N, unsafe.n, N)
	fmt.Printf("  %d 次自增：加锁得到   %d（一定是 %d）\n", N, safe.n, N)

	// ---- 6. 起很多 goroutine ----
	fmt.Println("\n=== 6. goroutine 很便宜 ===")
	spawnMany(20000)

	// ---- 7. 每个 goroutine 自己 recover ----
	fmt.Println("\n=== 7. 每个 goroutine 自己 recover ===")
	wg3 := new(sync.WaitGroup)
	wg3.Add(1)
	go func() {
		defer wg3.Done()
		defer func() {
			if r := recover(); r != nil {
				fmt.Println("  worker 内 recover:", r)
			}
		}()
		panic("worker 炸了")
	}()
	wg3.Wait()
	// 注意：如果不在 goroutine 内部 recover，这个 panic 会让整个程序崩溃，
	// 而且主协程的 recover 拦不住（呼应 d18）

	// safeGo 内部没有等，所以这里用 channel 精确等它完成
	fin := make(chan struct{})
	safeGo("A", func() { fin <- struct{}{} })
	<-fin
	fmt.Println("  A 正常完成")
}

package main

import (
	"fmt"
	"sort"
	"sync"
)

// ============ 1. 无缓冲 channel：发送和接收必须相遇 ============

func rendezvous() {
	ch := make(chan int) // 无缓冲

	// 如果先发送再接收且都在主协程，会死锁（这里先起 goroutine 接收）
	go func() {
		v := <-ch // 阻塞等待
		fmt.Println("  接收方拿到:", v)
	}()

	ch <- 42 // 阻塞直到有人接收
	fmt.Println("  发送方完成发送：42")
}

// ============ 2. 有缓冲 channel：发送方不阻塞 ============

func buffered() {
	ch := make(chan string, 3) // 容量 3
	ch <- "A"
	ch <- "B"
	fmt.Printf("  缓冲 3 已放 2 个，len=%d cap=%d（发送方都没被阻塞）\n", len(ch), cap(ch))
	ch <- "C"
	fmt.Printf("  放满 3 个后 len=%d\n", len(ch))
	// 第四个会阻塞，因为缓冲满了
	// ch <- "D"  ← 取消注释会卡住

	close(ch) // 关闭后仍能把缓冲区里的取完
	for v := range ch {
		fmt.Println("  range 读到:", v)
	}
}

// ============ 3. close 的三个后果 ============

func closeSemantics() {
	ch := make(chan int, 2)
	ch <- 1
	ch <- 2
	close(ch)

	// 后果一：关闭后仍能取完缓冲区里的值
	v1, ok1 := <-ch
	v2, ok2 := <-ch
	fmt.Printf("  缓冲区排空：v1=%d ok1=%v, v2=%d ok2=%v\n", v1, ok1, v2, ok2)

	// 后果二：排空后接收立刻返回零值，ok=false（不阻塞！）
	v3, ok3 := <-ch
	fmt.Printf("  再接收：v3=%d（零值）ok3=%v  ← 立刻返回，没有阻塞\n", v3, ok3)

	// 不带 ok 的接收同样返回零值
	v4 := <-ch
	fmt.Printf("  单值接收：v4=%d（零值，无法区分关闭和「有人发了 0」）\n", v4)

	// 后果三：往已关闭的 channel 发送会 panic
	// ch <- 999  ← 取消注释：panic: send on closed channel
	fmt.Println("  往已关闭 channel 发送会 panic（已注释）")
}

// ============ 4. range 遍历：生产者负责 close ============

// producer 是标准模式：返回 channel，内部 goroutine 跑完后 close
func producer(n int) <-chan int {
	ch := make(chan int)
	go func() {
		defer close(ch) // ← 必须有，否则 range 永远不结束
		for i := 1; i <= n; i++ {
			ch <- i * 10
		}
	}()
	return ch
}

// consumer 消费到 channel 关闭为止
func consumer(ch <-chan int) []int {
	var out []int
	for v := range ch { // close 后自动结束
		out = append(out, v)
	}
	return out
}

// ============ 5. 不 close 也可以：条数确定时用计数 ============

func batchByCount(n int) []int {
	ch := make(chan int)
	go func() {
		for i := 1; i <= n; i++ {
			ch <- i
		}
		// 注意：这里不 close，因为接收方知道要收几个
	}()

	out := make([]int, 0, n)
	for i := 0; i < n; i++ {
		out = append(out, <-ch) // 收够 n 个就走
	}
	return out
}

// ============ 6. 死锁演示（注释掉就跑不了）============

func deadlockSelf() {
	ch := make(chan int)
	ch <- 1 // ← 阻塞在这里：没人接收
	fmt.Println(<-ch)
	// 运行会输出：fatal error: all goroutines are asleep - deadlock!
}

// ============ 7. 并发 worker 池：结果顺序要排序才稳定 ============

type Job struct {
	ID   int
	Name string
}

type Result struct {
	JobID int
	Out   string
}

// pool 用「固定数量 worker + 结果 channel」处理 job 列表
func pool(jobs []Job, workers int) []Result {
	jobCh := make(chan Job, len(jobs)) // 缓冲 = len(jobs)：所有 job 都能立刻发出去
	resCh := make(chan Result, len(jobs)) // 同样给足缓冲，避免 worker 卡在发送上

	var wg sync.WaitGroup
	for w := 0; w < workers; w++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for j := range jobCh { // range 在 jobCh 关闭后自动结束
				resCh <- Result{JobID: j.ID, Out: fmt.Sprintf("%s-处理完", j.Name)}
			}
		}()
	}

	// 生产者：发完所有 job 然后关闭
	go func() {
		for _, j := range jobs {
			jobCh <- j
		}
		close(jobCh) // ← 关闭信号，worker 的 range 才能结束
	}()

	wg.Wait()        // 等所有 worker 结束
	close(resCh)     // worker 都停了，才关闭结果 channel
	return collect(resCh) // range 结果
}

func collect(ch <-chan Result) []Result {
	var out []Result
	for r := range ch {
		out = append(out, r)
	}
	// 并发结果顺序不保证，排序让输出确定
	sort.Slice(out, func(i, j int) bool { return out[i].JobID < out[j].JobID })
	return out
}

// ============ 8. 只接收的 channel 永远不 close ============

func receiveOnlyChannel() {
	// 只读的 channel（chan<- 是发送方向，<-chan 是接收方向）
	ch := make(chan int, 2)
	ch <- 7
	var recvOnly <-chan int = ch
	fmt.Printf("  只接收 channel 读到: %d\n", <-recvOnly)
	// 注意：接收方向的 channel 不 close——没有「发送方」这个角色
}

// ============ 9. WaitGroup + channel 组合：等一组，等一个 ============

func waitBoth() {
	var wg sync.WaitGroup
	results := make(chan string, 3)

	for _, name := range []string{"A", "B", "C"} {
		wg.Add(1)
		go func(n string) {
			defer wg.Done()
			results <- n + " 完成"
		}(name)
	}

	wg.Wait()               // 等一组
	close(results)          // 然后关闭，才能 range

	var all []string
	for r := range results {
		all = append(all, r)
	}
	sort.Strings(all) // 并发顺序不定，排序
	fmt.Println("  WaitGroup+channel:", all)
}

func main() {
	// ---- 1. 无缓冲 ----
	fmt.Println("=== 1. 无缓冲 channel：必须相遇 ===")
	rendezvous()

	// ---- 2. 有缓冲 ----
	fmt.Println("\n=== 2. 有缓冲 channel ===")
	buffered()

	// ---- 3. close 语义 ----
	fmt.Println("\n=== 3. close 的三个后果 ===")
	closeSemantics()

	// ---- 4. range + close ----
	fmt.Println("\n=== 4. range 遍历：生产者 close ===")
	rs := consumer(producer(3))
	fmt.Println("  收到:", rs, "（range 在 close 后自动结束）")

	// ---- 5. 计数代替 close ----
	fmt.Println("\n=== 5. 条数确定时不用 close ===")
	fmt.Println("  batchByCount(4) =", batchByCount(4))

	// ---- 6. 死锁 ----
	fmt.Println("\n=== 6. 死锁演示 ===")
	fmt.Println("  下面这行会 fatal error: all goroutines are asleep - deadlock!")
	fmt.Println("  deadlockSelf() 里先 ch <- 1 再 <-ch，同一个 goroutine 给自己发再收 → 死锁")
	// deadlockSelf() // 取消注释试试

	// ---- 7. worker 池 ----
	fmt.Println("\n=== 7. worker 池 ===")
	jobs := []Job{{1, "任务甲"}, {2, "任务乙"}, {3, "任务丙"}, {4, "任务丁"}, {5, "任务戊"}}
	out := pool(jobs, 3) // 3 个 worker 处理 5 个 job
	for _, r := range out {
		fmt.Printf("  job%d → %s\n", r.JobID, r.Out)
	}

	// ---- 8. 方向性 channel ----
	fmt.Println("\n=== 8. 方向性 channel ===")
	receiveOnlyChannel()

	// ---- 9. WaitGroup + channel ----
	fmt.Println("\n=== 9. WaitGroup + channel ===")
	waitBoth()

	fmt.Println("\n记住三条：发送方负责 close；用 range 就必须 close；条数确定可以用计数免 close。")
}

package main

import (
	"context"
	"errors"
	"fmt"
	"sort"
	"sync"
	"time"
)

var (
	ErrTimeout = errors.New("等待超时")
	ErrClosed  = errors.New("channel 已关闭")
)

// ============ 1. 超时：用 select + time.After ============

func recvWithTimeout(ch <-chan int, d time.Duration) (int, error) {
	select {
	case v, ok := <-ch:
		if !ok {
			return 0, ErrClosed
		}
		return v, nil
	case <-time.After(d):
		return 0, ErrTimeout
	}
}

// ============ 2. nil channel 禁用某个 case ============

// recvOptional：timeout <= 0 表示「不设超时」，用 nil channel 禁用 timeout 分支
func recvOptional(ch <-chan int, timeout time.Duration) (int, error) {
	var timeoutCh <-chan time.Time // 零值 nil：接收 nil channel 永久阻塞
	if timeout > 0 {
		t := time.NewTimer(timeout)
		defer t.Stop()
		timeoutCh = t.C
	}

	select {
	case v, ok := <-ch:
		if !ok {
			return 0, ErrClosed
		}
		return v, nil
	case <-timeoutCh:
		return 0, ErrTimeout // 只有设了超时才会到这
	}
}

// ============ 3. 多路复用：合并多个 channel（fan-in）============

// fanIn 把多个 channel 合并成一个，这是 S13 并发抓取器的核心模式
func fanIn(chans ...<-chan int) <-chan int {
	out := make(chan int)
	var wg sync.WaitGroup
	wg.Add(len(chans))
	for _, ch := range chans {
		go func(c <-chan int) {
			defer wg.Done()
			for v := range c {
				out <- v
			}
		}(ch)
	}
	go func() {
		wg.Wait()
		close(out) // 所有来源都结束后才关闭
	}()
	return out
}

// ============ 4. 优雅退出：ctx 模式的 select（d22 会详讲）============

// worker 是所有并发任务的标准循环体形态：for + select + ctx.Done()
func worker(ctx context.Context, in <-chan int, out chan<- int) {
	for {
		select {
		case <-ctx.Done():
			return // 被取消，立刻退出
		case v, ok := <-in:
			if !ok {
				return // 输入结束
			}
			select {
			case out <- v * 10:
			case <-ctx.Done():
				return // 发送也要能被打断
			}
		}
	}
}

// ============ 5. default：非阻塞发送（满了就丢）============

func trySend(ch chan int, v int) bool {
	select {
	case ch <- v:
		return true // 成功放入
	default:
		return false // 满了，丢弃
	}
}

// 非阻塞接收：只试一次，没数据就走
func tryRecv(ch chan int) (int, bool) {
	select {
	case v := <-ch:
		return v, true
	default:
		return 0, false
	}
}

// ============ 6. 计时器版（生产推荐）：NewTimer + Stop ============

func recvWithTimer(ch <-chan int, d time.Duration) (int, error) {
	t := time.NewTimer(d)
	defer t.Stop() // ← 关键：不再需要时释放，避免 timer 堆积
	select {
	case v, ok := <-ch:
		if !ok {
			return 0, ErrClosed
		}
		return v, nil
	case <-t.C:
		return 0, ErrTimeout
	}
}

// ============ 7. select 是「执行一次」，要处理多个值要套 for ============

func drain(ch <-chan int) []int {
	var out []int
	for { // 外层 for
		select { // 内层 select 执行一次
		case v, ok := <-ch:
			if !ok {
				return out // 关闭了，返回
			}
			out = append(out, v)
		default:
			return out // 暂时没数据，先走（这里演示 default 使其非阻塞）
		}
	}
}

func main() {
	// ---- 1. 超时 ----
	fmt.Println("=== 1. select 超时 ===")
	fast := make(chan int, 1)
	fast <- 1
	v, err := recvWithTimeout(fast, 50*time.Millisecond)
	fmt.Printf("  快通道: v=%d err=%v\n", v, err)

	slow := make(chan int) // 没有任何人发送
	v2, err2 := recvWithTimeout(slow, 30*time.Millisecond)
	fmt.Printf("  慢通道: v=%d err=%v  ← 30ms 后走超时分支\n", v2, err2)

	// timer 版效果相同
	v2b, err2b := recvWithTimer(slow, 30*time.Millisecond)
	fmt.Printf("  NewTimer 版: v=%d err=%v\n", v2b, err2b)

	// ---- 2. nil channel 禁用 case ----
	fmt.Println("\n=== 2. nil channel 禁用 timeout 分支 ===")
	ready := make(chan int, 1)
	ready <- 99
	v3, err3 := recvOptional(ready, 0) // timeout=0 → timeoutCh 是 nil → 该 case 永不触发
	fmt.Printf("  timeout=0（禁用）: v=%d err=%v  ← 不会被卡住\n", v3, err3)
	v4, err4 := recvOptional(slow, 20*time.Millisecond) // 有超时
	fmt.Printf("  timeout=20ms: v=%d err=%v\n", v4, err4)

	// ---- 3. fan-in 合并 ----
	fmt.Println("\n=== 3. fan-in 合并多个 channel ===")
	a := make(chan int, 2)
	b := make(chan int, 2)
	c := make(chan int, 2)
	a <- 1
	a <- 2
	b <- 3
	b <- 4
	c <- 5
	c <- 6
	close(a)
	close(b)
	close(c)

	merged := fanIn(a, b, c)
	var got []int
	for v := range merged { // merged 在所有来源结束后被 close
		got = append(got, v)
	}
	sort.Ints(got) // 合并顺序不确定，排序让输出确定
	fmt.Println("  合并后（已排序）:", got)

	// ---- 4. default：非阻塞收发 ----
	fmt.Println("\n=== 4. default：非阻塞 ===")
	buf := make(chan int, 2)
	fmt.Printf("  trySend(1)=%v trySend(2)=%v trySend(3)=%v  ← 第三个满了被丢\n", trySend(buf, 1), trySend(buf, 2), trySend(buf, 3))
	for {
		val, ok := tryRecv(buf)
		if !ok {
			break
		}
		fmt.Println("  tryRecv 读到:", val)
	}
	if _, ok := tryRecv(buf); !ok {
		fmt.Println("  缓冲空了，tryRecv 立刻返回 false（不阻塞）")
	}

	// ---- 5. drain 用 default 非阻塞排空 ----
	fmt.Println("\n=== 5. default 非阻塞排空 ===")
	dc := make(chan int, 3)
	dc <- 1
	dc <- 2
	fmt.Println("  drain 得到:", drain(dc))
	fmt.Println("  再 drain 空 channel:", drain(dc), "（default 让它立刻返回）")

	// ---- 6. worker + context（d22 预告）----
	fmt.Println("\n=== 6. worker + context（优雅退出的标准形态）====")
	ctx, cancel := context.WithCancel(context.Background())
	in := make(chan int)
	out := make(chan int, 10)
	go worker(ctx, in, out)

	in <- 1
	in <- 2
	in <- 3
	close(in)
	time.Sleep(30 * time.Millisecond) // 让 worker 处理完
	cancel()                         // 取消（模拟关闭服务）

	var results []int
	for {
		v, ok := tryRecv(out)
		if !ok {
			break
		}
		results = append(results, v)
	}
	sort.Ints(results)
	fmt.Println("  worker 输出（已排序）:", results, "  ← 1,2,3 各自 *10")

	fmt.Println("\n记住四条：多个就绪时伪随机选；time.After 有 timer 代价；nil channel 在 select 里永不触发；default 让 select 立刻返回。")
}

package main

import (
	"context"
	"errors"
	"fmt"
	"sort"
	"sync"
	"time"
)

// ============ 1. 基础：WithCancel 手动取消 ============

func workerBasic(ctx context.Context, id int, wg *sync.WaitGroup, out chan<- string) {
	defer wg.Done()
	select {
	case <-ctx.Done():
		out <- fmt.Sprintf("worker%d 收到取消: %v", id, ctx.Err())
	case <-time.After(50 * time.Millisecond):
		out <- fmt.Sprintf("worker%d 正常完成", id)
	}
}

// ============ 2. WithTimeout：到点自动取消 ============

func slowOp(ctx context.Context, d time.Duration) (string, error) {
	select {
	case <-time.After(d):
		return "完成", nil
	case <-ctx.Done():
		return "", fmt.Errorf("slowOp 中断: %w", ctx.Err())
	}
}

// ============ 3. 取消沿派生链向下传播，向上不传播 ============

// demoPropagation 展示：父取消 → 所有子都收到；子超时 → 父不受影响
func demoPropagation() {
	// 父：5 秒超时
	parent, cancelParent := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancelParent()

	// 子 1：继承父，自己 1 秒超时
	child1, cancel1 := context.WithTimeout(parent, 100*time.Millisecond)
	defer cancel1()
	// 子 2：继承父，自己手动取消
	child2, cancel2 := context.WithCancel(parent)
	defer cancel2()
	// 孙：继承子 2
	grand, cancelGrand := context.WithCancel(child2)
	defer cancelGrand()

	fmt.Printf("  初始：parent.Err=%v child1.Err=%v\n", parent.Err(), child1.Err())

	// 等 child1 超时
	<-child1.Done()
	fmt.Printf("  child1 超时后：child1.Err=%v（DeadlineExceeded）\n", child1.Err())
	fmt.Printf("  parent.Err=%v（nil：子超时不影响父）\n", parent.Err())

	// 手动取消 child2 → grand 也收到（向下传播）
	cancel2()
	<-grand.Done()
	fmt.Printf("  取消 child2 后：grand.Err=%v（Canceled，信号向下传播）\n", grand.Err())
	fmt.Printf("  parent.Err=%v（依然是 nil：取消不能向上传播）\n", parent.Err())
}

// ============ 4. worker 的标准循环体（内层 select 也要能取消）============

// 标准形态：接收可取消 + 发送可取消 + 输入关闭退出
func workerStd(ctx context.Context, id int, in <-chan int, out chan<- string) {
	for {
		select {
		case <-ctx.Done():
			// 被取消：把原因带回去
			out <- fmt.Sprintf("worker%d 取消退出: %v", id, ctx.Err())
			return
		case v, ok := <-in:
			if !ok {
				out <- fmt.Sprintf("worker%d 正常结束（输入关闭）", id)
				return
			}
			// 内层 select：发送也必须能被 ctx 打断
			select {
			case out <- fmt.Sprintf("worker%d 处理 %d", id, v):
			case <-ctx.Done():
				out <- fmt.Sprintf("worker%d 发送时被取消", id)
				return
			}
		}
	}
}

// ============ 5. 超时的错误要能区分 Canceled 和 DeadlineExceeded ============

type OpError struct {
	Op  string
	Err error
}

func (e *OpError) Error() string { return fmt.Sprintf("操作 %s 失败: %v", e.Op, e.Err) }
func (e *OpError) Unwrap() error { return e.Err }

// mapToStatus 把 context 错误映射成 HTTP 状态码（S4 会用）
func mapToStatus(err error) int {
	switch {
	case errors.Is(err, context.DeadlineExceeded):
		return 504 // 网关超时
	case errors.Is(err, context.Canceled):
		return 499 // 客户端断开（nginx 的约定码）
	case errors.Is(err, ErrNotFound):
		return 404
	default:
		return 500
	}
}

var ErrNotFound = errors.New("资源不存在")

// ============ 6. errgroup 风格：并发 + 全部等 + 收集第一个错误 ============

// fetchAll 并发跑 N 个任务，返回第一个错误和成功数
func fetchAll(ctx context.Context, n int, work func(ctx context.Context, i int) error) (success int, firstErr error) {
	ctx, cancel := context.WithCancel(ctx) // 任一任务失败就取消其余
	defer cancel()

	var mu sync.Mutex
	var wg sync.WaitGroup
	for i := 0; i < n; i++ {
		wg.Add(1)
		go func(idx int) {
			defer wg.Done()
			if err := work(ctx, idx); err != nil {
				mu.Lock()
				if firstErr == nil {
					firstErr = err
					cancel() // 通知其他任务别干了
				}
				mu.Unlock()
				return
			}
			mu.Lock()
			success++
			mu.Unlock()
		}(i)
	}
	wg.Wait()
	return success, firstErr
}

func main() {
	// ---- 1. WithCancel ----
	fmt.Println("=== 1. WithCancel 手动取消 ===")
	ctx1, cancel1 := context.WithCancel(context.Background())
	out1 := make(chan string, 3)
	var wg sync.WaitGroup
	wg.Add(2)
	go workerBasic(ctx1, 1, &wg, out1)
	go workerBasic(ctx1, 2, &wg, out1)
	cancel1() // 立刻取消所有
	wg.Wait()
	close(out1)
	var lines1 []string
	for l := range out1 {
		lines1 = append(lines1, l)
	}
	sort.Strings(lines1)
	for _, l := range lines1 {
		fmt.Println("  ", l)
	}

	// ---- 2. WithTimeout ----
	fmt.Println("\n=== 2. WithTimeout 自动取消 ===")
	ctx2, cancel2 := context.WithTimeout(context.Background(), 30*time.Millisecond)
	defer cancel2()
	start := time.Now()
	s, err := slowOp(ctx2, 200*time.Millisecond) // 操作要 200ms，但只有 30ms
	fmt.Printf("  结果=%q err=%v（耗时 %v，ctx 超时了）\n", s, err, time.Since(start).Milliseconds())

	ctx3, cancel3 := context.WithTimeout(context.Background(), time.Second)
	defer cancel3()
	s3, err3 := slowOp(ctx3, 10*time.Millisecond) // 操作 10ms，来得及
	fmt.Printf("  结果=%q err=%v（操作比超时快，完成了）\n", s3, err3)

	// ---- 3. 传播方向 ----
	fmt.Println("\n=== 3. 取消的传播方向 ===")
	demoPropagation()

	// ---- 4. 标准 worker 循环体 ----
	fmt.Println("\n=== 4. worker 标准循环体 ===")
	ctx4, cancel4 := context.WithCancel(context.Background())
	in4 := make(chan int, 5)
	out4 := make(chan string, 10)
	for i := 1; i <= 2; i++ {
		go workerStd(ctx4, i, in4, out4)
	}
	in4 <- 10
	in4 <- 20
	close(in4) // 关闭输入 → worker 正常结束
	time.Sleep(30 * time.Millisecond)
	cancel4()
	time.Sleep(30 * time.Millisecond)
	close(out4)
	var lines4 []string
	for l := range out4 {
		lines4 = append(lines4, l)
	}
	sort.Strings(lines4)
	for _, l := range lines4 {
		fmt.Println("  ", l)
	}

	// ---- 5. 错误分类 ----
	fmt.Println("\n=== 5. context 错误映射成状态码 ===")
	ctx5, cancel5 := context.WithTimeout(context.Background(), 20*time.Millisecond)
	defer cancel5()
	_, err5 := slowOp(ctx5, 100*time.Millisecond)
	wrapped := &OpError{Op: "加载成员", Err: err5}
	var oe *OpError
	fmt.Printf("  wrapped=%v\n", wrapped)
	fmt.Printf("  errors.As 取出 Op=%q\n", func() string {
		if errors.As(wrapped, &oe) {
			return oe.Op
		}
		return ""
	}())
	fmt.Printf("  errors.Is(DeadlineExceeded)=%v → HTTP %d\n", errors.Is(wrapped, context.DeadlineExceeded), mapToStatus(wrapped))
	fmt.Printf("  DeadlineExceeded → %d；Canceled → %d；其他 → %d\n", mapToStatus(context.DeadlineExceeded), mapToStatus(context.Canceled), mapToStatus(ErrNotFound))

	// ---- 6. errgroup 风格：一个失败取消其余 ----
	fmt.Println("\n=== 6. 一个失败，全部取消 ===")
	ctx6, cancel6 := context.WithCancel(context.Background())
	defer cancel6()
	ok, firstErr := fetchAll(ctx6, 5, func(c context.Context, i int) error {
		if i == 2 {
			return ErrNotFound // 第 3 个任务失败
		}
		select {
		case <-time.After(50 * time.Millisecond):
			return nil
		case <-c.Done():
			return c.Err() // 其他任务被取消
		}
	})
	fmt.Printf("  成功=%d 第一个错误=%v\n", ok, firstErr)
	fmt.Printf("  被取消的任务（context.Canceled）→ HTTP %d\n", mapToStatus(context.Canceled))

	fmt.Println("\n记住：ctx 第一个参数、defer cancel()、只用它的取消能力、业务数据走参数。")
}

package main

import (
	"fmt"
	"runtime"
	"sort"
	"sync"
	"sync/atomic"
)

// ============ 1. WaitGroup：等一组 ============

type Task struct {
	ID   int
	Name string
}

type TaskResult struct {
	ID   int
	Note string
}

func runTasks(tasks []Task, workers int) []TaskResult {
	jobCh := make(chan Task, len(tasks))
	resCh := make(chan TaskResult, len(tasks))

	var wg sync.WaitGroup // 等所有 worker 退出
	for i := 0; i < workers; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done() // 必须在 goroutine 第一行
			for t := range jobCh { // jobCh 关闭后自动结束
				resCh <- TaskResult{ID: t.ID, Note: t.Name + " 完成"}
			}
		}()
	}

	go func() {
		for _, t := range tasks {
			jobCh <- t
		}
		close(jobCh)
	}()

	wg.Wait()
	close(resCh)

	var out []TaskResult
	for r := range resCh {
		out = append(out, r)
	}
	sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
	return out
}

// ============ 2. Mutex：保护共享计数 ============

type UnsafeCounter struct{ n int } // 有竞争

func (c *UnsafeCounter) Inc() { c.n++ } // 读-改-写，非原子

type SafeCounter struct {
	mu sync.Mutex
	n  int
}

func (c *SafeCounter) Inc() {
	c.mu.Lock()
	defer c.mu.Unlock() // defer：即使 panic 也会解锁
	c.n++
}

func (c *SafeCounter) Get() int {
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.n
}

// ============ 3. RWMutex：读多写少 ============

type SafeCache struct {
	mu sync.RWMutex // 读写锁
	m  map[string]int
}

func NewSafeCache() *SafeCache {
	return &SafeCache{m: make(map[string]int)}
}

func (c *SafeCache) Get(k string) (int, bool) {
	c.mu.RLock() // 读锁：多个读者可并发
	defer c.mu.RUnlock()
	v, ok := c.m[k]
	return v, ok
}

func (c *SafeCache) Set(k string, v int) {
	c.mu.Lock() // 写锁：独占
	defer c.mu.Unlock()
	c.m[k] = v
}

// ============ 4. atomic：单变量原子操作 ============

type AtomicCounter struct {
	n int64 // 必须 64 位对齐（在 32 位平台要用 int64）
}

func (c *AtomicCounter) Inc() int64 { return atomic.AddInt64(&c.n, 1) }
func (c *AtomicCounter) Get() int64 { return atomic.LoadInt64(&c.n) }

// 演示「atomic 不能保证检查后行动」
type Flag struct {
	ready atomic.Bool
	count int // 非原子
}

func (f *Flag) TryInit() bool {
	// 即使检查用了 atomic，写 count 仍然竞争——atomic 只保证单操作原子
	if f.ready.Load() {
		return false
	}
	f.count = 1 // ← 这里的写和另一 goroutine 的写竞争
	f.ready.Store(true)
	return true
}

// ============ 5. 单例的并发初始化：sync.Once ============

type Config struct {
	DSN string
}

var (
	once   sync.Once
	config *Config
)

func GetConfig() *Config {
	once.Do(func() { // 保证初始化函数只执行一次
		config = &Config{DSN: "postgres://localhost/homecube"}
	})
	return config
}

// ============ 6. 检测 goroutine 泄漏：runtime.NumGoroutine ============

func goroutineCount() int {
	return runtime.NumGoroutine()
}

func main() {
	// ---- 1. WaitGroup ----
	fmt.Println("=== 1. WaitGroup 等一组 ===")
	tasks := []Task{{1, "任务甲"}, {2, "任务乙"}, {3, "任务丙"}, {4, "任务丁"}}
	for _, r := range runTasks(tasks, 2) {
		fmt.Printf("  job%d: %s\n", r.ID, r.Note)
	}

	// ---- 2. Mutex ----
	fmt.Println("\n=== 2. Mutex 保护共享计数 ===")
	const N = 10000
	unsafeC := &UnsafeCounter{}
	safeC := &SafeCounter{}
	var wg sync.WaitGroup
	for i := 0; i < N; i++ {
		wg.Add(1)
		go func() { defer wg.Done(); unsafeC.Inc() }()
	}
	wg.Wait()
	for i := 0; i < N; i++ {
		wg.Add(1)
		go func() { defer wg.Done(); safeC.Inc() }()
	}
	wg.Wait()
	fmt.Printf("  不加锁: %d（< %d 说明有丢失更新）\n", unsafeC.n, N)
	fmt.Printf("  加了锁: %d（精确）\n", safeC.Get())

	// ---- 3. RWMutex ----
	fmt.Println("\n=== 3. RWMutex 读写锁 ===")
	cache := NewSafeCache()
	cache.Set("a", 1)
	cache.Set("b", 2)
	// 多个读并发
	var wg2 sync.WaitGroup
	var mu sync.Mutex
	results := map[string]int{}
	for i := 0; i < 5; i++ {
		wg2.Add(1)
		go func() {
			defer wg2.Done()
			v, _ := cache.Get("a")
			mu.Lock()
			results["a"] = v
			mu.Unlock()
		}()
	}
	wg2.Wait()
	fmt.Printf("  并发读 cache[a] = %d\n", results["a"])

	// ---- 4. atomic ----
	fmt.Println("\n=== 4. atomic 单变量原子 ===")
	ac := &AtomicCounter{}
	var wg3 sync.WaitGroup
	for i := 0; i < N; i++ {
		wg3.Add(1)
		go func() { defer wg3.Done(); ac.Inc() }()
	}
	wg3.Wait()
	fmt.Printf("  atomic 计数 = %d（精确，无锁但精确）\n", ac.Get())

	// ---- 5. sync.Once ----
	fmt.Println("\n=== 5. sync.Once 单例 ===")
	c1 := GetConfig()
	c2 := GetConfig()
	fmt.Printf("  两次 GetConfig 返回同一指针? %v（DSN=%s）\n", c1 == c2, c1.DSN)

	// ---- 6. goroutine 数对比：观察泄漏 ----
	fmt.Println("\n=== 6. goroutine 泄漏检测 ===")
	fmt.Printf("  启动 worker 前: %d 个 goroutine\n", goroutineCount())

	leaked := make(chan int) // 无缓冲，接收方故意不读
	var wg4 sync.WaitGroup
	wg4.Add(1)
	go func() {
		defer wg4.Done()
		leaked <- 42 // 永久阻塞：接收方永远不来
	}()

	time_ := goroutineCount()
	fmt.Printf("  启动泄漏 worker 后: %d 个（+1，这个 worker 卡在 <- 上）\n", time_)

	// 修好：让接收方来收
	ok := make(chan int)
	var wg5 sync.WaitGroup
	wg5.Add(1)
	go func() {
		defer wg5.Done()
		ok <- 42 // 有人收，不会卡
	}()
	fmt.Printf("  正确发送（有人收）: %d（worker 不泄漏，立即结束）\n", <-ok)

	// ---- 7. 结论 ----
	fmt.Println("\n=== 7. channel vs Mutex 的判断 ===")
	fmt.Println("  数据要在 goroutine 间「传递」→ channel（隐含同步）")
	fmt.Println("  只是共享修改同一变量→ Mutex/RWMutex/atomic")
	fmt.Println("  用 go run -race ./lab/s1/d23 跑一次，看 UnsafeCounter 的竞争报告")
}

package main

import (
	"context"
	"errors"
	"fmt"
	"runtime"
	"sort"
	"sync"
	"time"
)

// ============ 陷阱一：数据竞争（用 go run -race 抓）============

type BadCounter struct{ n int }

func (c *BadCounter) Inc() { c.n++ } // 无锁：go run -race 会报 DATA RACE

type GoodCounter struct {
	mu sync.Mutex
	n  int
}

func (c *GoodCounter) Inc() {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.n++
}

func (c *GoodCounter) Get() int {
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.n
}

// ============ 陷阱二：goroutine / channel 泄漏 ============

// leakBySend：往一个永远不会有人收的 channel 发送 → 永久阻塞
func leakBySend() {
	ch := make(chan int) // 无缓冲，且之后没人收
	go func() {
		ch <- 1 // ← 永久卡在这里，goroutine 泄漏
	}()
}

// safeBySend：接收方明确，发送不阻塞
func safeBySend() int {
	ch := make(chan int, 1) // 缓冲 1：即使还没人收也能放进去
	go func() { ch <- 1 }()  // 放完就结束，不泄漏
	return <-ch
}

// ============ 陷阱三：缺少 ctx.Done() 退路的 worker ============

// badWorker：发送没有退路，接收方走了就永久泄漏
func badWorker(ctx context.Context, in <-chan int, out chan<- string) {
	for {
		select {
		case <-ctx.Done():
			return // 接收这一层能取消，但……
		case v, ok := <-in:
			if !ok {
				return
			}
			// ……下面这行是裸发送：ctx 取消救不了它，所以它会永久卡住
			out <- fmt.Sprintf("badWorker 处理了 %d", v)
		}
	}
}

// goodWorker：标准形态，发送也可被取消
func goodWorker(ctx context.Context, in <-chan int, out chan<- string) {
	for {
		select {
		case <-ctx.Done():
			return
		case v, ok := <-in:
			if !ok {
				return
			}
			select {
			case out <- fmt.Sprintf("goodWorker 处理了 %d", v):
			case <-ctx.Done():
				return
			}
		}
	}
}

// ============ 陷阱四：非确定性输出 → 排序规整 ============

type Result struct {
	Idx   int
	Value int
}

// runConcurrent 并发算，返回**排序后**的结果（输出确定）
func runConcurrent(n int) ([]Result, int) {
	resCh := make(chan Result, n) // 缓冲 n：发送方永不阻塞
	var wg sync.WaitGroup

	for i := 1; i <= n; i++ {
		wg.Add(1)
		go func(idx int) {
			defer wg.Done()
			resCh <- Result{Idx: idx, Value: idx * idx}
		}(i)
	}
	wg.Wait()
	close(resCh)

	var out []Result
	for r := range resCh {
		out = append(out, r)
	}
	sort.Slice(out, func(i, j int) bool { return out[i].Idx < out[j].Idx }) // 排序让输出确定
	return out, n
}

// ============ 陷阱五：死锁（只演示，不真跑）============

// deadlockDemo 如果真调用会 fatal error（所有 goroutine 都阻塞）
func deadlockDemo() {
	ch := make(chan int)
	ch <- 1 // ← 同一个 goroutine 给自己发，永远等不到接收
	fmt.Println(<-ch)
}

// ============ S1 综合：struct + method + interface 隐式实现 + error 包装 ============

// S1 判据第 1 条：徒手写出这四样
type MemberDTO struct {
	ID      string `json:"id"`
	Name    string `json:"name"`
	Joined  string `json:"joined_at"`
	private int    // 未导出字段不参与序列化
}

// 方法：指针接收者（要修改内部状态）
func (m *MemberDTO) Rename(name string) error {
	if name == "" {
		return errors.New("新名字不能为空")
	}
	m.Name = name
	return nil
}

// Stringer：fmt 见到它就会用 String() 格式化
func (m MemberDTO) String() string {
	return fmt.Sprintf("%s(%s) 加入于 %s", m.Name, m.ID, m.Joined)
}

// Notifier：接口在消费方定义，实现方零声明
type Notifier interface {
	Notify(msg string) error
}

// EmailNotifier 隐式实现 Notifier（指针接收者）
type EmailNotifier struct{ sent []string }

func (e *EmailNotifier) Notify(msg string) error {
	e.sent = append(e.sent, msg)
	return nil
}

// 编译期断言：确保 EmailNotifier 满足 Notifier
var _ Notifier = (*EmailNotifier)(nil)

// Store：接口作为函数参数（依赖倒置）
type Store interface {
	Save(m MemberDTO) error
	Find(id string) (MemberDTO, error)
}

type memStore struct{ items map[string]MemberDTO }

func newMemStore() *memStore { return &memStore{items: map[string]MemberDTO{}} }

func (s *memStore) Save(m MemberDTO) error {
	if m.ID == "" {
		return errors.New("ID 不能为空")
	}
	s.items[m.ID] = m
	return nil
}

func (s *memStore) Find(id string) (MemberDTO, error) {
	m, ok := s.items[id]
	if !ok {
		return MemberDTO{}, fmt.Errorf("成员 %s: %w", id, ErrNotFound)
	}
	return m, nil
}

var ErrNotFound = errors.New("不存在")

// Service 依赖接口而非实现
type MemberService struct {
	store    Store
	notifier Notifier
	clock    Clock
}

type Clock interface{ Now() time.Time }

type fixedClock struct{ t time.Time }

func (f fixedClock) Now() time.Time { return f.t }

func NewMemberService(store Store, notifier Notifier, clk Clock) *MemberService {
	return &MemberService{store: store, notifier: notifier, clock: clk}
}

// Register 用 %w 包装错误链（S1 判据第 1 条）
func (s *MemberService) Register(name string) error {
	if name == "" {
		return errors.New("name 不能为空")
	}
	m := MemberDTO{ID: "m_" + name, Name: name, Joined: s.clock.Now().Format("2006-01-02")}
	if err := s.store.Save(m); err != nil {
		return fmt.Errorf("保存成员 %s: %w", name, err)
	}
	return s.notifier.Notify("新成员 " + name + " 已加入")
}

func (s *MemberService) Get(id string) (MemberDTO, error) {
	m, err := s.store.Find(id)
	if err != nil {
		return MemberDTO{}, fmt.Errorf("查询 %s: %w", id, err)
	}
	return m, nil
}

// ============ goroutine 数测量 ============

func numGoroutine() int { return runtime.NumGoroutine() }

func main() {
	// ---- 1. 数据竞争：对比不加锁 vs 加锁 ----
	fmt.Println("=== 1. 数据竞争（go run -race 看详情）===")
	const N = 20000
	bad := &BadCounter{}
	good := &GoodCounter{}
	var wg sync.WaitGroup
	for i := 0; i < N; i++ {
		wg.Add(1)
		go func() { defer wg.Done(); bad.Inc() }()
		wg.Add(1)
		go func() { defer wg.Done(); good.Inc() }()
	}
	wg.Wait()
	fmt.Printf("  %d 次自增：不加锁=%d（< %d，丢失更新）\n", N, bad.n, N)
	fmt.Printf("  %d 次自增：加了锁=%d（精确）\n", N, good.Get())
	fmt.Println("  结论：不加锁那个每次运行都不同但一定 < 20000，这就是数据竞争的签名")

	// ---- 2. goroutine 泄漏：可测量 ----
	fmt.Println("\n=== 2. goroutine 泄漏检测 ===")
	base := numGoroutine()
	fmt.Printf("  起点: %d 个 goroutine\n", base)

	leakBySend()
	time.Sleep(100 * time.Millisecond)
	afterLeak := numGoroutine()
	fmt.Printf("  启动泄漏任务后: %d 个（比起点多 %d）\n", afterLeak, afterLeak-base)
	fmt.Println("  这些 goroutine 永久卡在 ch <- 1，因为接收方永远不会来")

	v := safeBySend()
	fmt.Printf("  正确写法（缓冲 channel）: 收到 %d，goroutine 数回到 %d\n", v, numGoroutine())

	// ---- 3. 缺少 ctx.Done() 退路的 worker ----
	fmt.Println("\n=== 3. worker 的发送退路 ===")
	ctx, cancel := context.WithCancel(context.Background())

	// 两个 worker 必须用**各自独立**的输入 channel：否则它们抢同一个 channel，
	// 哪个值归谁是不确定的，输出就没法断言了。
	badIn := make(chan int, 4)   // badWorker 的输入
	goodIn := make(chan int, 4)  // goodWorker 的输入
	badOut := make(chan string, 4)
	goodOut := make(chan string, 4)

	go badWorker(ctx, badIn, badOut)
	go goodWorker(ctx, goodIn, goodOut)

	// 每个 channel 各给两个值（缓冲 4，发送方不会被阻塞）
	badIn <- 1
	badIn <- 2
	goodIn <- 1
	goodIn <- 2
	time.Sleep(50 * time.Millisecond) // 等两个 worker 都处理完

	var badMsgs, goodMsgs []string
	for len(badOut) > 0 {
		badMsgs = append(badMsgs, <-badOut)
	}
	for len(goodOut) > 0 {
		goodMsgs = append(goodMsgs, <-goodOut)
	}
	sort.Strings(badMsgs)
	sort.Strings(goodMsgs)
	fmt.Printf("  badWorker 处理的: %v（它也能收 ctx，但发送那一步卡住时救不回来）\n", badMsgs)
	fmt.Printf("  goodWorker 处理的: %v（发送有 ctx 退路）\n", goodMsgs)

	cancel()
	close(badIn)
	close(goodIn)
	time.Sleep(50 * time.Millisecond)
	fmt.Println("  取消后：goodWorker 正常退出，badWorker 若还卡在发送就永久泄漏")

	// ---- 4. 非确定性 → 排序规整 ----
	fmt.Println("\n=== 4. 并发输出的确定性 ===")
	results, n := runConcurrent(4)
	var parts []string
	for _, r := range results {
		parts = append(parts, fmt.Sprintf("%d²=%d", r.Idx, r.Value))
	}
	fmt.Printf("  %d 个并发任务，排序后: %v\n", n, parts)
	fmt.Println("  每次运行这行输出都完全一样——因为我们收集后排序了")

	// ---- 5. 死锁（只说明不执行）----
	fmt.Println("\n=== 5. 死锁（只说明不执行）===")
	fmt.Println("  deadlockDemo() 里先 ch <- 1 再 <-ch，同一个 goroutine 给自己发再收")
	fmt.Println("  真调用会 fatal error: all goroutines are asleep - deadlock!（非 0 退出）")

	// ---- 6. S1 综合：struct + method + interface + %w ----
	fmt.Println("\n=== 6. S1 判据：struct + method + 隐式 interface + error 包装 ===")
	clk := fixedClock{t: time.Date(2026, 10, 15, 9, 0, 0, 0, time.UTC)}
	store := newMemStore()
	notifier := &EmailNotifier{}
	svc := NewMemberService(store, notifier, clk) // 依赖注入：三个接口

	if err := svc.Register("小林"); err != nil {
		fmt.Println("  注册失败:", err)
	} else {
		fmt.Println("  注册成功")
	}
	m, err := svc.Get("m_小林")
	fmt.Printf("  查到: %s（%+v）\n", m, m)

	// 错误链：errors.Is 能穿透所有层
	_, err = svc.Get("m_不存在")
	fmt.Printf("  查不到: %v\n", err)
	fmt.Printf("  errors.Is(err, ErrNotFound) = %v  ← %w 包装保住了链\n", errors.Is(err, ErrNotFound))

	// 改名：指针接收者的方法真的改了状态
	if err := m.Rename("小林改名"); err != nil {
		fmt.Println("  改名失败:", err)
	} else {
		fmt.Printf("  改名后: %s\n", m)
	}
	fmt.Printf("  notifier 收到 %d 条通知\n", len(notifier.sent))

	// ---- 7. 泄漏体检总结 ----
	fmt.Println("\n=== 7. 泄漏体检 ===")
	final := numGoroutine()
	fmt.Printf("  结束时: %d 个 goroutine（起点 %d）\n", final, base)
	fmt.Println("  leakBySend 那个 goroutine 一定还在（永久卡在 ch <- 1），它不会被回收")
	fmt.Println("  在服务里表现为：内存缓慢增长、文件句柄/连接耗尽、最后 OOM 或 too many open files")

	fmt.Println("\n=== S1 收口 ===")
	fmt.Println("请运行 bash scripts/s1-check.sh，逐条检验四周的 24 个学习目标。")
}
